type GoalLinkageDecision={id:string;parentGoalId:string;triggeringChildVersionId:string;decision:"keep_parent"|"adjust_parent"|null;status:string;reason:string|null;generatedChangeRequestId:string|null;childGoalId:string;childOwnerName:string;childAmount:string;decidedAt:string|null;parentLevel:GoalLevel;parentAmount:string;canDecide:boolean};
