type GoalHistory={versions:Array<{id:string;versionNo:string;amount:string;previousAmount:string|null;amountDifference:string|null;status:string;createdByName:string;signedByName:string|null;signatureText:string|null;signedAt:string|null;changeReason:string;createdAt:string}>;approvals:Array<{id:string;goalVersionId:string;stage:string;decision:string;decidedByName:string;comment:string|null;decidedAt:string}>;changeRequests:Array<{id:string;requestedAmount:string|null;reason:string;status:string;outcomeComment:string|null;createdAt:string;requestedByName:string;handledByName:string|null}>;audit:Array<{id:string;action:string;entityType:string;entityId:string;actorName:string|null;beforeData:unknown;afterData:unknown;createdAt:string}>};
