const roleNames: Record<string, string> = { system_admin: "系统管理员", sales_assistant: "销售助理", sales_assistant_leader: "销售助理组长", sales_manager: "销售经理", sales_supervisor: "业务主管", sales_leader: "业务员组长", salesperson: "业务员", hr: "人事部", general_manager: "总经理" };
function businessDateToday():string{const parts=new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date());const value=(type:Intl.DateTimeFormatPartTypes)=>parts.find((part)=>part.type===type)?.value??"";return `${value("year")}-${value("month")}-${value("day")}`;}

function readCsrfToken(): string | null {
  const cookie = document.cookie.split("; ").find((item) => item.startsWith("sampleflow_csrf="));
  return cookie ? decodeURIComponent(cookie.slice("sampleflow_csrf=".length)) : null;
}

async function apiFetch(input: RequestInfo | URL, init: RequestInit = {}): Promise<Response> {
  const method = (init.method ?? "GET").toUpperCase();
  const headers = new Headers(init.headers);
  if (!["GET", "HEAD", "OPTIONS"].includes(method)) {
    const csrfToken = readCsrfToken();
    if (csrfToken) headers.set("x-csrf-token", csrfToken);
  }
  return fetch(input, { ...init, headers });
}

async function readResponseJson<T>(response:Response,fallback:string):Promise<T>{
  try{return await response.json() as T;}catch{throw new Error(fallback);}
}

function passwordStrength(password: string): "弱" | "中" | "强" {
  const categoryCount = [/[a-z]/, /[A-Z]/, /[0-9]/, /[^A-Za-z0-9]/].filter((pattern) => pattern.test(password)).length;
  if (password.length >= 12 && categoryCount === 4) return "强";
  if (password.length >= 8 && categoryCount >= 3) return "中";
  return "弱";
}

function PasswordInput({id,name,label,value,onChange,autoComplete,describedBy,invalid=false}:{id:string;name:string;label:string;value:string;onChange:(value:string)=>void;autoComplete:"current-password"|"new-password";describedBy?:string;invalid?:boolean}){
  const[visible,setVisible]=useState(false);
  const inputRef=useRef<HTMLInputElement>(null);
  function toggleVisibility(){if(inputRef.current&&inputRef.current.value!==value)onChange(inputRef.current.value);setVisible((current)=>!current);}
  return <><label htmlFor={id}>{label}</label><div className="password-input"><input ref={inputRef} id={id} name={name} type={visible?"text":"password"} defaultValue={value} onChange={(event)=>onChange(event.target.value)} autoComplete={autoComplete} aria-describedby={describedBy} aria-invalid={invalid||undefined}/><button type="button" className="password-input-toggle" aria-label={`${visible?"隐藏":"显示"}${label}`} aria-pressed={visible} onClick={toggleVisibility}>{visible?<EyeOff size={18} aria-hidden="true"/>:<Eye size={18} aria-hidden="true"/>}</button></div></>;
}

async function getCurrentUser(): Promise<User | null> {
  const response = await apiFetch("/api/auth/me");
  if (response.status === 401) return null;
  if (!response.ok) throw new Error("无法读取登录状态");
  return (await response.json() as { user: User }).user;
}

export function App() {
  const [auth, setAuth] = useState<AuthState>({ status: "loading" });
  useEffect(() => { getCurrentUser().then((user) => setAuth(user ? { status: "authenticated", user } : { status: "guest" })).catch(() => setAuth({ status: "guest" })); }, []);
  if (auth.status === "loading") return <div className="app-loading">正在连接 SampleFlow…</div>;
  if (auth.status === "guest") return <Login onLogin={(user) => setAuth({ status: "authenticated", user })} />;
  if (auth.user.mustChangePassword) return <ChangePassword onChanged={async()=>{const user=await getCurrentUser();if(user)setAuth({status:"authenticated",user});}}/>;
  return <Dashboard user={auth.user} onLogout={() => setAuth({ status: "guest" })} />;
}

function ChangePassword({onChanged}:{onChanged:()=>Promise<void>}){
  const[currentPassword,setCurrentPassword]=useState("");
  const[newPassword,setNewPassword]=useState("");
  const[message,setMessage]=useState("");
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const formData=new FormData(event.currentTarget);const submittedCurrentPassword=String(formData.get("currentPassword")??"");const submittedNewPassword=String(formData.get("newPassword")??"");const response=await apiFetch("/api/auth/change-password",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({currentPassword:submittedCurrentPassword,newPassword:submittedNewPassword})});const data=await response.json() as {message?:string};if(!response.ok){setMessage(data.message??"密码修改失败");return;}await onChanged();}
  const currentPasswordError=message==="当前密码错误";
  return <main className="password-shell"><section className="login-card"><div className="login-heading"><p>首次登录安全设置</p><h2>请修改初始密码</h2><span>6—128 位，并包含英文字母、数字和符号</span></div><form noValidate onSubmit={submit}><PasswordInput id="current-password" name="currentPassword" label="当前密码" value={currentPassword} onChange={(value)=>{setCurrentPassword(value);if(message)setMessage("");}} autoComplete="current-password" describedBy={`current-password-hint${currentPasswordError?" current-password-error":""}`} invalid={currentPasswordError}/><p id="current-password-hint" className="password-hint">当前密码请填写刚才登录时使用的临时密码。</p><PasswordInput id="new-password" name="newPassword" label="新密码" value={newPassword} onChange={(value)=>{setNewPassword(value);if(message)setMessage("");}} autoComplete="new-password"/><p className="password-strength" aria-live="polite">密码强度：{passwordStrength(newPassword)}</p><button type="submit">保存新密码</button>{message?<p id={currentPasswordError?"current-password-error":undefined} className="form-error" role="alert">{message}</p>:null}</form></section></main>;
}

function Login({ onLogin }: { onLogin: (user: User) => void }) {
  const [username, setUsername] = useState(import.meta.env.DEV ? "sales_assistant" : "");
  const [password, setPassword] = useState(import.meta.env.DEV ? "SampleFlow@2026" : "");
  const [message, setMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [readiness, setReadiness] = useState<"checking" | "ready" | "unavailable">("checking");
  useEffect(() => {
    let active = true;
    let controller: AbortController | null = null;
    const checkReadiness = async () => {
      controller?.abort();
      controller = new AbortController();
      try {
        const response = await fetch("/api/ready", { cache: "no-store", signal: controller.signal });
        if (active) setReadiness(response.ok ? "ready" : "unavailable");
      } catch (error) {
        if (error instanceof DOMException && error.name === "AbortError") return;
        if (active) setReadiness("unavailable");
      }
    };
    void checkReadiness();
    const timer = window.setInterval(checkReadiness, 5_000);
    return () => { active = false; controller?.abort(); window.clearInterval(timer); };
  }, []);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setSubmitting(true); setMessage("");
    try {
      const formData = new FormData(event.currentTarget);
      const submittedUsername = String(formData.get("username") ?? "");
      const submittedPassword = String(formData.get("password") ?? "");
      const response = await apiFetch("/api/auth/login", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ username:submittedUsername, password:submittedPassword }) });
      const data = await readResponseJson<{ message?: string }>(response, "登录服务暂时不可用，请确认 API 已启动后重试");
      if (!response.ok) throw new Error(data.message ?? "登录失败");
      const user = await getCurrentUser();
      if (!user) throw new Error("登录会话创建失败");
      onLogin(user);
    } catch (error) { setMessage(error instanceof Error ? error.message : "登录失败"); }
    finally { setSubmitting(false); }
  }
  return <main className="login-shell">
    <section className="brand-panel"><div className="brand-mark">SF</div><div className="brand-copy"><p className="product-name">SampleFlow</p><h1>每一笔业绩，都有清晰的来路与责任。</h1><p className="brand-summary">面向销售到样业务的目标、订单、组织归属与审批系统。历史不重写，调整有事件，结果可追溯。</p></div><div className="principles"><div><Activity size={20} /><span>实时业绩事件</span></div><div><ShieldCheck size={20} /><span>角色权限分离</span></div><div><Database size={20} /><span>集中数据与审计</span></div></div></section>
    <section className="login-panel"><div className="login-card"><div className="login-heading"><p>销售到样业绩管理</p><h2>登录系统</h2><span>{import.meta.env.DEV ? "开发环境已预填销售助理演示账号" : "请使用管理员分配的账号登录"}</span></div><form noValidate onSubmit={submit}><label htmlFor="username">账号</label><input id="username" name="username" value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" /><PasswordInput id="password" name="password" label="密码" value={password} onChange={setPassword} autoComplete="current-password"/><button type="submit" disabled={submitting}>{submitting ? "正在登录…" : "进入 SampleFlow"}<ChevronRight size={18} /></button>{message ? <p className="form-error" role="alert">{message}</p> : null}</form><div className={`readiness readiness-${readiness}`} role="status" aria-live="polite"><span />{{checking:"正在检查 API 与数据库",ready:"前端、API 与数据库已连接",unavailable:"API 或数据库暂不可用"}[readiness]}</div></div></section>
  </main>;
}

function Dashboard({ user, onLogout }: { user: User; onLogout: () => void }) {
  type PageId = "overview"|"goals"|"orders"|"organization"|"approvals"|"accounts";
  const pages = [
    user.capabilities.viewPerformance ? {id:"overview" as const,Icon:BarChart3,label:"业绩总览"} : null,
    user.capabilities.viewGoals ? {id:"goals" as const,Icon:Target,label:"目标管理"} : null,
    user.capabilities.viewPerformance ? {id:"orders" as const,Icon:ClipboardCheck,label:"订单业绩"} : null,
    user.capabilities.viewOrganization ? {id:"organization" as const,Icon:Network,label:"组织架构"} : null,
    user.capabilities.viewApprovals ? {id:"approvals" as const,Icon:FileClock,label:"审批中心"} : null,
    user.capabilities.manageAccounts ? {id:"accounts" as const,Icon:UsersRound,label:"账号管理"} : null,
  ].filter((page):page is NonNullable<typeof page>=>page!==null);
  const [active, setActive] = useState<PageId>(user.capabilities.manageAccounts ? "accounts" : pages[0]?.id??"overview");
  async function logout() { await apiFetch("/api/auth/logout", { method: "POST" }); onLogout(); }
  const content = active === "orders"
    ? <OrdersPage user={user} />
    : active === "goals"
      ? <GoalsPage user={user} pendingOnly={false} />
      : active === "approvals"
        ? <GoalsPage user={user} pendingOnly />
      : active === "organization"
        ? <OrganizationPage user={user}/>
      : active === "accounts"
        ? <AccountsPage user={user}/>
      : <Overview canEdit={user.capabilities.editPerformance} canExport={user.capabilities.exportPerformance} onEnterOrders={() => setActive("orders")} />;
  return <div className="app-shell"><aside className="sidebar"><div className="sidebar-brand"><span>SF</span><strong>SampleFlow</strong></div><nav>{pages.map(({Icon,label,id}) => <button className={id === active ? "active" : ""} key={id} onClick={() => setActive(id)} aria-label={label} aria-current={id===active?"page":undefined}><Icon size={18}/><span>{label}</span></button>)}</nav><div className="sidebar-user"><div className="avatar">{user.displayName.slice(0,1)}</div><div><strong>{user.displayName}</strong><span>{user.roles.map((r) => roleNames[r] ?? r).join("、")}</span></div><button onClick={logout} aria-label="退出登录"><LogOut size={17}/></button></div></aside>{content}</div>;
}

function AccountsPage({user}:{user:User}){
  const [users,setUsers]=useState<AdminUser[]>([]);const [roles,setRoles]=useState<Array<{code:string;name:string}>>([]);const [permissionMatrix,setPermissionMatrix]=useState<RolePermission[]>([]);const [message,setMessage]=useState("");const [showCreate,setShowCreate]=useState(false);const [temporaryCredential,setTemporaryCredential]=useState<{username:string;password:string;expiresAt:string}|null>(null);const isAdmin=user.capabilities.manageAccounts;
  const load=useCallback(async()=>{if(!isAdmin)return;const response=await fetch("/api/admin/users");const data=await response.json() as {users?:AdminUser[];roles?:Array<{code:string;name:string}>;permissionMatrix?:RolePermission[];message?:string};if(!response.ok)throw new Error(data.message??"账号加载失败");setUsers(data.users??[]);setRoles(data.roles??[]);setPermissionMatrix(data.permissionMatrix??[]);},[isAdmin]);useEffect(()=>{load().catch((error)=>setMessage(error instanceof Error?error.message:"账号加载失败"));},[load]);
  async function toggle(item:AdminUser){const response=await apiFetch(`/api/admin/users/${item.id}/status`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({isActive:!item.isActive})});const data=await response.json() as {message?:string};if(!response.ok){setMessage(data.message??"状态修改失败");return;}await load();}
  async function resetPassword(item:AdminUser){const response=await apiFetch(`/api/admin/users/${item.id}/reset-password`,{method:"POST",headers:{"content-type":"application/json"},body:"{}"});const data=await response.json() as {message?:string;temporaryPassword?:string;temporaryPasswordExpiresAt?:string};if(!response.ok||!data.temporaryPassword||!data.temporaryPasswordExpiresAt){setMessage(data.message??"密码重置失败");return;}setTemporaryCredential({username:item.username,password:data.temporaryPassword,expiresAt:data.temporaryPasswordExpiresAt});await load();}
  return <main className="dashboard"><header><div><h1>账号管理</h1><p>系统管理权限与业务权限分离；业务角色必须显式分配</p></div>{isAdmin?<button className="primary-action" onClick={()=>setShowCreate(true)}><Plus size={16}/>创建账号</button>:null}</header>{!isAdmin?<div className="permission-note"><ShieldCheck size={18}/>仅独立系统管理员可以维护账号和角色。</div>:null}{message?<p className="page-message">{message}</p>:null}{isAdmin?<><section className="orders-card"><div className="orders-toolbar"><div><h2>系统账号</h2><span>{users.length} 个账号</span></div></div><div className="orders-table-wrap"><table><thead><tr><th>账号</th><th>姓名</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody>{users.map((item)=><tr key={item.id}><td>{item.username}</td><td>{item.displayName}</td><td>{item.roles.map((role)=>roleNames[role]??role).join("、")}</td><td><span className={`status ${item.isActive?"status-active":"status-paused"}`}>{item.isActive?"启用":"停用"}</span></td><td><div className="table-actions"><button className="table-action" onClick={()=>resetPassword(item)}>重置密码</button><button className="table-action" onClick={()=>toggle(item)}>{item.isActive?"停用":"启用"}</button></div></td></tr>)}</tbody></table></div></section><section className="orders-card permission-matrix-card" aria-labelledby="permission-matrix-title"><div className="orders-toolbar"><div><h2 id="permission-matrix-title">角色权限说明</h2><span>多角色账号取各角色权限并集；系统管理员角色本身不增加业务权限</span></div></div><div className="orders-table-wrap"><table className="permission-matrix-table"><thead><tr><th>角色</th><th>数据范围</th><th>业务操作</th><th>目标职责</th><th>导出权限</th><th>明确禁止</th></tr></thead><tbody>{permissionMatrix.length===0?<tr><td colSpan={6} className="empty-cell">暂无角色权限定义</td></tr>:permissionMatrix.map((item)=><tr key={item.code}><td><strong>{item.name}</strong></td><td><span className={`scope-badge scope-${item.businessScope}`}>{scopeName(item.businessScope)}</span></td><td>{item.businessOperations.join("；")}</td><td>{item.targetResponsibilities}</td><td>{item.exportPermission}</td><td>{item.forbidden.join("；")}</td></tr>)}</tbody></table></div></section></>:null}{showCreate?<CreateAccount roles={roles} onClose={()=>setShowCreate(false)} onSaved={async()=>{setShowCreate(false);await load();}}/>:null}{temporaryCredential?<Modal title="临时密码已生成" note="该密码只显示一次，24 小时后失效" onClose={()=>setTemporaryCredential(null)}><div className="temporary-password-result"><p>账号：{temporaryCredential.username}</p><strong>{temporaryCredential.password}</strong><span>失效时间：{new Date(temporaryCredential.expiresAt).toLocaleString("zh-CN")}</span><div className="modal-actions"><button type="button" onClick={()=>setTemporaryCredential(null)}>我已安全保存</button></div></div></Modal>:null}</main>;
}

function scopeName(scope:RolePermission["businessScope"]):string{return{none:"无业务范围",self:"仅本人",group:"本人及所负责小组",department:"本人及所负责部门",all:"全公司 / 销售组织"}[scope];}

function CreateAccount({roles,onClose,onSaved}:{roles:Array<{code:string;name:string}>;onClose:()=>void;onSaved:()=>Promise<void>}){const[username,setUsername]=useState("");const[displayName,setDisplayName]=useState("");const[role,setRole]=useState(roles[0]?.code??"salesperson");const[personId,setPersonId]=useState("");const[people,setPeople]=useState<PersonOption[]>([]);const[error,setError]=useState("");const[created,setCreated]=useState<{temporaryPassword:string;temporaryPasswordExpiresAt:string}|null>(null);useEffect(()=>{fetch("/api/admin/people").then(async(response)=>{const data=await response.json() as {people?:PersonOption[];message?:string};if(!response.ok)throw new Error(data.message??"人员列表加载失败");setPeople((data.people??[]).filter((person)=>!person.username));}).catch((reason)=>setError(reason instanceof Error?reason.message:"人员列表加载失败"));},[]);async function submit(event:FormEvent){event.preventDefault();const response=await apiFetch("/api/admin/users",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({username,displayName,roles:[role],personId:personId?Number(personId):null})});const data=await response.json() as {message?:string;temporaryPassword?:string;temporaryPasswordExpiresAt?:string};if(!response.ok||!data.temporaryPassword||!data.temporaryPasswordExpiresAt){setError(data.message??"创建失败");return;}setCreated({temporaryPassword:data.temporaryPassword,temporaryPasswordExpiresAt:data.temporaryPasswordExpiresAt});}return <Modal title="创建系统账号" note="可绑定已有人员身份；临时密码只显示一次，24 小时内必须完成首次改密" onClose={onClose}>{created?<div className="temporary-password-result"><p>请立即安全保存临时密码，关闭后无法再次查看。</p><strong>{created.temporaryPassword}</strong><span>失效时间：{new Date(created.temporaryPasswordExpiresAt).toLocaleString("zh-CN")}</span><div className="modal-actions"><button type="button" onClick={async()=>{await onSaved();}}>我已安全保存</button></div></div>:<form noValidate className="business-form" onSubmit={submit}><div className="form-grid"><Field label="登录账号" value={username} onChange={setUsername}/><Field label="账号显示姓名" value={displayName} onChange={setDisplayName}/><label className="field"><span>绑定已有人员（可选）</span><select value={personId} onChange={(event)=>setPersonId(event.target.value)}><option value="">新建人员身份</option>{people.map((person)=><option key={person.id} value={person.id}>{person.displayName}</option>)}</select></label><label className="field"><span>角色</span><select value={role} onChange={(event)=>setRole(event.target.value)}>{roles.map((item)=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label></div>{error?<p className="form-error">{error}</p>:null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit">创建账号</button></div></form>}</Modal>}

function OrganizationPage({user}:{user:User}){const[units,setUnits]=useState<OrgUnit[]>([]);const[assignments,setAssignments]=useState<Assignment[]>([]);const[message,setMessage]=useState("");const[dialog,setDialog]=useState<"unit"|"assignment"|"transfer"|null>(null);const isAdmin=user.capabilities.manageOrganization;const load=useCallback(async()=>{const response=await fetch("/api/organization");const data=await response.json() as {units?:OrgUnit[];assignments?:Assignment[];message?:string};if(!response.ok)throw new Error(data.message??"组织架构加载失败");setUnits(data.units??[]);setAssignments(data.assignments??[]);},[]);useEffect(()=>{load().catch((error)=>setMessage(error instanceof Error?error.message:"组织架构加载失败"));},[load]);return <main className="dashboard"><header><div><h1>组织架构</h1><p>组织与人员任职按生效日期管理；业绩入账时固化组织快照</p></div>{isAdmin?<div className="header-actions"><button className="secondary-action" onClick={()=>setDialog("transfer")}>办理组织异动</button><button className="secondary-action" onClick={()=>setDialog("assignment")}>新增任职</button><button className="primary-action" onClick={()=>setDialog("unit")}><Plus size={16}/>新增组织</button></div>:null}</header>{message?<p className="page-message">{message}</p>:null}<section className="org-grid"><article className="orders-card"><div className="orders-toolbar"><div><h2>部门与小组</h2><span>{units.length} 个组织单元</span></div></div><div className="compact-list">{units.map((unit)=><div key={unit.id}><span>{unit.unitType==="department"?"部门":"小组"}</span><strong>{unit.name}</strong><small>{unit.parentName??"顶层"}</small></div>)}</div></article><article className="orders-card"><div className="orders-toolbar"><div><h2>人员任职</h2><span>{assignments.length} 条有效期记录</span></div></div><div className="compact-list">{assignments.length?assignments.map((item)=><div key={item.id}><span>{item.effectiveFrom}{item.effectiveTo?` 至 ${item.effectiveTo}`:" 起"}</span><strong>{item.displayName}</strong><small>{[item.departmentName,item.groupName].filter(Boolean).join(" / ")}</small></div>):<p className="empty-cell">暂无人员任职记录</p>}</div></article></section>{dialog==="unit"?<CreateOrgUnit units={units} onClose={()=>setDialog(null)} onSaved={async()=>{setDialog(null);await load();}}/>:null}{dialog==="assignment"||dialog==="transfer"?<CreateAssignment units={units} closePrevious={dialog==="transfer"} onClose={()=>setDialog(null)} onSaved={async()=>{setDialog(null);await load();}}/>:null}</main>}

function CreateOrgUnit({units,onClose,onSaved}:{units:OrgUnit[];onClose:()=>void;onSaved:()=>Promise<void>}){const[name,setName]=useState("");const[unitType,setUnitType]=useState<"department"|"group">("department");const[parentId,setParentId]=useState("");const[error,setError]=useState("");async function submit(event:FormEvent){event.preventDefault();const response=await apiFetch("/api/admin/organization/units",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name,unitType,parentId:parentId?Number(parentId):null})});const data=await response.json() as {message?:string};if(!response.ok){setError(data.message??"新增组织失败");return;}await onSaved();}return <Modal title="新增组织单元" note="小组必须归属于一个部门" onClose={onClose}><form noValidate className="business-form" onSubmit={submit}><Field label="名称" value={name} onChange={setName}/><label className="field"><span>类型</span><select value={unitType} onChange={(e)=>setUnitType(e.target.value as "department"|"group")}><option value="department">部门</option><option value="group">小组</option></select></label>{unitType==="group"?<label className="field"><span>所属部门</span><select required value={parentId} onChange={(e)=>setParentId(e.target.value)}><option value="">请选择</option>{units.filter((u)=>u.unitType==="department").map((u)=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label>:null}{error?<p className="form-error">{error}</p>:null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit">保存组织</button></div></form></Modal>}

function CreateAssignment({units,closePrevious=false,onClose,onSaved}:{units:OrgUnit[];closePrevious?:boolean;onClose:()=>void;onSaved:()=>Promise<void>}){const[people,setPeople]=useState<PersonOption[]>([]);const[personId,setPersonId]=useState("");const[departmentId,setDepartmentId]=useState("");const[groupId,setGroupId]=useState("");const[leaderPersonId,setLeaderPersonId]=useState("");const[supervisorPersonId,setSupervisorPersonId]=useState("");const[effectiveFrom,setEffectiveFrom]=useState(businessDateToday);const[error,setError]=useState("");useEffect(()=>{fetch("/api/admin/people").then(async(response)=>{const data=await response.json() as {people?:PersonOption[];message?:string};if(!response.ok)throw new Error(data.message??"人员列表加载失败");setPeople(data.people??[]);}).catch((reason)=>setError(reason instanceof Error?reason.message:"人员列表加载失败"));},[]);async function submit(event:FormEvent){event.preventDefault();const response=await apiFetch("/api/admin/organization/assignments",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({personId:Number(personId),departmentId:Number(departmentId),groupId:Number(groupId),leaderPersonId:Number(leaderPersonId),supervisorPersonId:Number(supervisorPersonId),effectiveFrom,effectiveTo:null,closePrevious})});const data=await response.json() as {message?:string};if(!response.ok){setError(data.message??"任职保存失败");return;}await onSaved();}const personSelect=(label:string,value:string,onChange:(value:string)=>void)=><label className="field"><span>{label}</span><select required value={value} onChange={(event)=>onChange(event.target.value)}><option value="">请选择</option>{people.map((item)=><option key={item.id} value={item.id}>{item.displayName}{item.username?`（${item.username}）`:"（无登录账号）"}</option>)}</select></label>;return <Modal title={closePrevious?"办理组织异动":"新增人员任职"} note={closePrevious?"系统将于新任职生效日前一天结束原任职；历史业绩归属不会重写":"成员归属与负责人职责均按生效日期保存；新任职不改写历史事件"} onClose={onClose}><form noValidate className="business-form" onSubmit={submit}><div className="form-grid">{personSelect("任职人员",personId,setPersonId)}<Field label="生效日期" value={effectiveFrom} type="date" onChange={setEffectiveFrom}/><label className="field"><span>部门</span><select required value={departmentId} onChange={(event)=>{setDepartmentId(event.target.value);setGroupId("");}}><option value="">请选择</option>{units.filter((unit)=>unit.unitType==="department").map((unit)=><option key={unit.id} value={unit.id}>{unit.name}</option>)}</select></label><label className="field"><span>小组</span><select required value={groupId} onChange={(event)=>setGroupId(event.target.value)}><option value="">请选择</option>{units.filter((unit)=>unit.unitType==="group"&&unit.parentId===departmentId).map((unit)=><option key={unit.id} value={unit.id}>{unit.name}</option>)}</select></label>{personSelect("小组负责人",leaderPersonId,setLeaderPersonId)}{personSelect("部门主管",supervisorPersonId,setSupervisorPersonId)}</div>{error?<p className="form-error">{error}</p>:null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit">{closePrevious?"确认异动":"保存任职"}</button></div></form></Modal>}

type GoalDialog={kind:"sign"|"approve"|"reject"|"request";goal:Goal};
type WorkflowDialog={kind:"accept"|"reject";request:GoalChangeRequest}|{kind:"linkage";linkage:GoalLinkageDecision};

function allocationText(goal:Goal){if(goal.allocationType==="balanced")return "已完全分配";const label=goal.allocationType==="overallocated"?"超分配":"未分配";return `${label} ${formatMoney(Math.abs(Number(goal.allocationDifference)))}${goal.allocationRatio?`（${goal.allocationRatio}%）`:""}`;}
function differenceText(value:string|null){if(value===null)return "—";const number=Number(value);return `${number>0?"+":""}${formatMoney(number)}`;}
function auditDataText(value:unknown){return value===null||value===undefined?"—":JSON.stringify(value);}

function GoalsPage({ user, pendingOnly }: { user: User; pendingOnly: boolean }) {
  const [goals,setGoals]=useState<Goal[]>([]);const[workflows,setWorkflows]=useState<GoalWorkflows>({changeRequests:[],linkageDecisions:[]});
  const[showCreate,setShowCreate]=useState(false);const[message,setMessage]=useState("");const[loading,setLoading]=useState(true);
  const[formalGoal,setFormalGoal]=useState<Goal|null>(null);const[historyGoal,setHistoryGoal]=useState<Goal|null>(null);
  const[goalDialog,setGoalDialog]=useState<GoalDialog|null>(null);const[workflowDialog,setWorkflowDialog]=useState<WorkflowDialog|null>(null);const[busyWorkflowId,setBusyWorkflowId]=useState<string|null>(null);
  const canCreate=user.roles.some((role)=>["sales_manager","sales_supervisor","sales_leader"].includes(role));
  const load=useCallback(async()=>{setLoading(true);try{const [goalResponse,workflowResponse]=await Promise.all([fetch(pendingOnly?"/api/goals?pendingOnly=true":"/api/goals"),pendingOnly?fetch("/api/goal-workflows"):Promise.resolve(null)]);const goalData=await readResponseJson<{goals?:Goal[];message?:string}>(goalResponse,"目标响应无效，请重试。");if(!goalResponse.ok)throw new Error(goalData.message??"目标加载失败");setGoals(goalData.goals??[]);if(workflowResponse){const workflowData=await readResponseJson<GoalWorkflows&{message?:string}>(workflowResponse,"目标待办响应无效，请重试。");if(!workflowResponse.ok)throw new Error(workflowData.message??"目标待办加载失败");setWorkflows({changeRequests:workflowData.changeRequests??[],linkageDecisions:workflowData.linkageDecisions??[]});}}finally{setLoading(false);}},[pendingOnly]);
  useEffect(()=>{load().catch((error)=>setMessage(error instanceof Error?error.message:"目标加载失败"));},[load]);
  async function withdraw(item:GoalChangeRequest){if(busyWorkflowId)return;setBusyWorkflowId(item.id);setMessage("");try{const response=await apiFetch(`/api/goal-change-requests/${item.id}/withdraw`,{method:"POST",headers:{"content-type":"application/json"},body:"{}"});const data=await readResponseJson<{message?:string}>(response,"撤回响应无效，请重试。");if(!response.ok){setMessage(data.message??"撤回失败");return;}try{await load();setMessage("修改申请已撤回，可以基于当前生效目标重新申请。");}catch{setMessage("修改申请已撤回，但列表刷新失败，请手动刷新页面。");}}catch(error){setMessage(error instanceof Error?error.message:"网络异常，撤回失败，请重试。");}finally{setBusyWorkflowId(null);}}
  const refreshed=async(note:string)=>{setGoalDialog(null);setWorkflowDialog(null);try{await load();setMessage(note);}catch{setMessage(`${note} 列表刷新失败，请手动刷新页面。`);}};
  return <main className="dashboard goals-page"><header><div><h1>{pendingOnly?"审批中心":"目标管理"}</h1><p>{pendingOnly?"处理目标审批、修改申请和逐级联动选择":"按组织责任逐级下达，签名和审批均绑定具体版本"}</p></div><div className="header-actions">{user.capabilities.exportGoals?<button className="secondary-action" onClick={()=>{window.location.href="/api/exports/goals.csv"}}>导出目标</button>:null}{canCreate&&!pendingOnly?<button className="primary-action" onClick={()=>setShowCreate(true)}><Plus size={16}/>下达目标</button>:null}</div></header>{message?<p className="page-message" role="status">{message}</p>:null}<section className="orders-card" aria-labelledby="goal-table-title"><div className="orders-toolbar"><div><h2 id="goal-table-title">{pendingOnly?"待签名与待审批目标":"目标责任台账"}</h2><span role="status">{loading?"正在读取…":`${goals.length} 条记录`}</span></div></div><div className="orders-table-wrap"><table><thead><tr><th>月份</th><th>层级 / 范围</th><th>责任人</th><th>目标</th><th>直接下级</th><th>分配差额</th><th>状态</th><th>操作</th></tr></thead><tbody>{!loading&&goals.length===0?<tr><td colSpan={8} className="empty-cell">{pendingOnly?"当前没有待签名或待审批目标。":"暂无目标；有下达权限的负责人可创建第一条目标。"}</td></tr>:goals.map((goal)=><tr key={goal.id}><td>{goal.periodMonth}</td><td><strong>{goalLevelName(goal.level)}</strong>{goal.orgUnitName?<small className="table-secondary">{goal.orgUnitName}</small>:null}</td><td>{goal.ownerName}</td><td>{formatMoney(goal.amount)}{goal.effectiveAmount!==null&&goal.effectiveAmount!==goal.amount?<small className="table-secondary">当前生效 {formatMoney(goal.effectiveAmount)}</small>:null}</td><td>{formatMoney(goal.allocatedAmount)}</td><td className={goal.allocationType==="overallocated"?"warning":""}>{allocationText(goal)}</td><td><span className={`status goal-${goal.status}`}>{goalStatusName(goal.status)}</span></td><td><div className="row-actions">{goal.status==="active"?<button onClick={()=>setFormalGoal(goal)}>查看正式报表</button>:null}<button onClick={()=>setHistoryGoal(goal)}>版本与记录</button>{goal.ownerPersonId===user.personId&&goal.status==="pending_signature"?<button onClick={()=>setGoalDialog({kind:"sign",goal})}>确认签名</button>:null}{goal.ownerPersonId===user.personId&&goal.level!=="sales_manager"&&goal.status==="active"?<button onClick={()=>setGoalDialog({kind:"request",goal})}>申请修改</button>:null}{goal.status==="pending_gm"&&user.roles.includes("general_manager")?<><button onClick={()=>setGoalDialog({kind:"approve",goal})}>批准</button><button className="danger-action" onClick={()=>setGoalDialog({kind:"reject",goal})}>拒绝</button></>:null}{goal.status==="pending_hr"&&user.roles.includes("hr")?<><button onClick={()=>setGoalDialog({kind:"approve",goal})}>批准</button><button className="danger-action" onClick={()=>setGoalDialog({kind:"reject",goal})}>拒绝</button></>:null}</div></td></tr>)}</tbody></table></div></section>{pendingOnly?<><WorkflowTable title="目标修改申请" empty="当前没有相关修改申请。" rows={workflows.changeRequests.map((item)=><tr key={item.id}><td>{goalLevelName(item.level)} · {item.ownerName}</td><td>{item.requestedByName}</td><td>{item.currentAmount?formatMoney(item.currentAmount):"—"}</td><td>{item.requestedAmount?formatMoney(item.requestedAmount):"由直属上级填写"}</td><td>{item.newAmount?formatMoney(item.newAmount):"尚未生成"}</td><td>{differenceText(item.amountDifference)}</td><td className="wrap-cell">{item.reason}{item.outcomeComment?<small className="table-secondary">处理意见：{item.outcomeComment}</small>:null}</td><td><span className={`status workflow-${item.status}`}>{workflowStatusName(item.status)}</span></td><td><div className="row-actions">{item.canHandle?<><button onClick={()=>setWorkflowDialog({kind:"accept",request:item})}>接受并填金额</button><button className="danger-action" onClick={()=>setWorkflowDialog({kind:"reject",request:item})}>拒绝</button></>:null}{item.canWithdraw?<button disabled={busyWorkflowId!==null} aria-busy={busyWorkflowId===item.id} onClick={()=>withdraw(item)}>{busyWorkflowId===item.id?"正在撤回…":"撤回"}</button>:null}</div></td></tr>)} headers={["目标","申请人","当前生效","建议金额","候选版本","版本差异","原因 / 意见","状态","操作"]}/><WorkflowTable title="目标联动选择" empty="当前没有待处理的目标联动。" rows={workflows.linkageDecisions.map((item)=><tr key={item.id}><td>{goalLevelName(item.parentLevel)}</td><td>{item.childOwnerName}</td><td>{formatMoney(item.childAmount)}</td><td>{formatMoney(item.parentAmount)}</td><td><span className={`status workflow-${item.status}`}>{workflowStatusName(item.status)}</span></td><td><div className="row-actions">{item.canDecide?<button onClick={()=>setWorkflowDialog({kind:"linkage",linkage:item})}>选择是否调整</button>:null}</div></td></tr>)} headers={["本级目标","变化的下级责任人","下级新目标","本级生效目标","状态","操作"]}/></>:null}{showCreate?<CreateGoal user={user} onClose={()=>setShowCreate(false)} onSaved={async()=>{setShowCreate(false);try{await load();setMessage("目标已下达，等待责任人确认签名。");}catch{setMessage("目标已下达，但列表刷新失败，请手动刷新页面。");}}}/>:null}{goalDialog?<GoalActionDialog dialog={goalDialog} user={user} onClose={()=>setGoalDialog(null)} onSaved={()=>refreshed(goalDialog.kind==="request"?"修改申请已提交。":"目标状态已更新。")}/>:null}{workflowDialog?<WorkflowActionDialog dialog={workflowDialog} onClose={()=>setWorkflowDialog(null)} onSaved={()=>refreshed("目标待办已处理。")}/>:null}{historyGoal?<GoalHistoryDialog goal={historyGoal} onClose={()=>setHistoryGoal(null)}/>:null}{formalGoal?<FormalReportDialog goal={formalGoal} onClose={()=>setFormalGoal(null)}/>:null}</main>;
}

function WorkflowTable({title,empty,headers,rows}:{title:string;empty:string;headers:string[];rows:ReactNode[]}){return <section className="orders-card workflow-card"><div className="orders-toolbar"><div><h2>{title}</h2><span>{rows.length} 条记录</span></div></div><div className="orders-table-wrap"><table><thead><tr>{headers.map((header)=><th key={header}>{header}</th>)}</tr></thead><tbody>{rows.length?rows:<tr><td colSpan={headers.length} className="empty-cell">{empty}</td></tr>}</tbody></table></div></section>}

function GoalActionDialog({dialog,user,onClose,onSaved}:{dialog:GoalDialog;user:User;onClose:()=>void;onSaved:()=>Promise<void>}){const[signature,setSignature]=useState(`${user.displayName}确认`);const[reason,setReason]=useState("");const[requestedAmount,setRequestedAmount]=useState("");const[comment,setComment]=useState("");const[error,setError]=useState("");const[saving,setSaving]=useState(false);const title=dialog.kind==="sign"?"确认目标版本":dialog.kind==="request"?"申请修改目标":dialog.kind==="approve"?"批准目标":"拒绝目标";async function submit(event:FormEvent){event.preventDefault();if(saving)return;setSaving(true);setError("");let url=`/api/goals/${dialog.goal.id}/decision`;let body:Record<string,unknown>={decision:dialog.kind==="reject"?"rejected":"approved",comment};if(dialog.kind==="sign"){url=`/api/goals/${dialog.goal.id}/sign`;body={signatureText:signature};}else if(dialog.kind==="request"){url=`/api/goals/${dialog.goal.id}/change-requests`;body={reason,...(requestedAmount?{requestedAmount:Number(requestedAmount)}:{})};}try{const response=await apiFetch(url,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const data=await readResponseJson<{message?:string}>(response,"服务响应无效，请重试。");if(!response.ok){setError(data.message??"操作失败");return;}await onSaved();}catch(failure){setError(failure instanceof Error?failure.message:"网络异常，操作失败，请重试。");}finally{setSaving(false);}}return <Modal title={title} note={`${dialog.goal.periodMonth} · ${goalLevelName(dialog.goal.level)} · 版本 ${dialog.goal.versionNo}`} onClose={onClose}><form noValidate className="business-form" onSubmit={submit}>{dialog.kind==="sign"?<Field label="签名确认" value={signature} onChange={setSignature}/>:dialog.kind==="request"?<div className="form-grid"><Field label="修改原因" value={reason} onChange={setReason}/><label className="field"><span>建议金额（可选）</span><input value={requestedAmount} type="number" min="0" step="0.01" onChange={(event)=>setRequestedAmount(event.target.value)}/></label></div>:<label className="field"><span>审批意见</span><textarea className="resize-none" rows={4} value={comment} onChange={(event)=>setComment(event.target.value)} placeholder={dialog.kind==="reject"?"拒绝时必须说明原因":"填写本次审批意见"}/></label>}{error?<p className="form-error" role="alert">{error}</p>:null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit" disabled={saving} aria-busy={saving}>{saving?"正在提交…":dialog.kind==="sign"?"提交签名":dialog.kind==="request"?"提交修改申请":dialog.kind==="approve"?"确认批准":"确认拒绝"}</button></div></form></Modal>}

function WorkflowActionDialog({dialog,onClose,onSaved}:{dialog:WorkflowDialog;onClose:()=>void;onSaved:()=>Promise<void>}){const isLinkage=dialog.kind==="linkage";const[decision,setDecision]=useState<"keep_parent"|"adjust_parent">("keep_parent");const[newAmount,setNewAmount]=useState(!isLinkage&&dialog.kind==="accept"?(dialog.request.requestedAmount??""):"");const[reason,setReason]=useState("");const[error,setError]=useState("");const[saving,setSaving]=useState(false);async function submit(event:FormEvent){event.preventDefault();if(saving)return;setSaving(true);setError("");let url:string;let body:Record<string,unknown>;if(isLinkage){url=`/api/goal-linkage-decisions/${dialog.linkage.id}/decide`;body={decision,reason,...(decision==="adjust_parent"&&dialog.linkage.parentLevel==="sales_manager"?{newAmount:Number(newAmount)}:{})};}else{url=`/api/goal-change-requests/${dialog.request.id}/${dialog.kind}`;body=dialog.kind==="accept"?{newAmount:Number(newAmount),comment:reason}:{comment:reason};}try{const response=await apiFetch(url,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const data=await readResponseJson<{message?:string}>(response,"服务响应无效，请重试。");if(!response.ok){setError(data.message??"待办处理失败");return;}await onSaved();}catch(failure){setError(failure instanceof Error?failure.message:"网络异常，待办处理失败，请重试。");}finally{setSaving(false);}}const title=isLinkage?"处理目标联动":dialog.kind==="accept"?"接受修改申请":"拒绝修改申请";return <Modal title={title} note={isLinkage?"不调整会保留本级签名；调整会逐级发起申请，绝不自动改金额":"直属目标下达人填写新金额，责任人需要重新签名"} onClose={onClose}><form noValidate className="business-form" onSubmit={submit}>{isLinkage?<><label className="field"><span>处理方式</span><select value={decision} onChange={(event)=>setDecision(event.target.value as "keep_parent"|"adjust_parent")}><option value="keep_parent">不调整本级目标，保留原签名</option><option value="adjust_parent">调整本级目标，发起上一级流程</option></select></label>{decision==="adjust_parent"&&dialog.linkage.parentLevel==="sales_manager"?<Field label="销售经理总目标新金额" value={newAmount} type="number" onChange={setNewAmount}/>:null}</>:dialog.kind==="accept"?<Field label="新目标金额" value={newAmount} type="number" onChange={setNewAmount}/>:null}<label className="field"><span>{isLinkage?"联动原因":"处理意见"}</span><textarea className="resize-none" rows={4} value={reason} onChange={(event)=>setReason(event.target.value)}/></label>{error?<p className="form-error" role="alert">{error}</p>:null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit" disabled={saving} aria-busy={saving}>{saving?"正在提交…":isLinkage?"确认联动选择":dialog.kind==="accept"?"接受并创建新版本":"确认拒绝"}</button></div></form></Modal>}

function GoalHistoryDialog({goal,onClose}:{goal:Goal;onClose:()=>void}){const[data,setData]=useState<GoalHistory|null>(null);const[error,setError]=useState("");useEffect(()=>{const controller=new AbortController();fetch(`/api/goals/${goal.id}/history`,{signal:controller.signal}).then(async(response)=>{const result=await readResponseJson<GoalHistory&{message?:string}>(response,"目标历史响应无效，请重试。");if(!response.ok)throw new Error(result.message??"目标历史加载失败");setData(result);}).catch((failure)=>{if(failure instanceof DOMException&&failure.name==="AbortError")return;setError(failure instanceof Error?failure.message:"目标历史加载失败");});return()=>controller.abort();},[goal.id]);return <Modal title="目标版本与操作记录" note={`${goal.periodMonth} · ${goal.ownerName} · 每次签名和审批均绑定具体版本`} onClose={onClose}>{error?<p className="form-error history-content" role="alert">{error}</p>:!data?<p className="history-content">正在读取版本与审计记录…</p>:<div className="history-content"><section><h3>版本与差异</h3><ol className="history-list">{data.versions.map((version)=><li key={version.id}><div><strong>版本 {version.versionNo} · {formatMoney(version.amount)}</strong><span className={`status goal-${version.status}`}>{goalStatusName(version.status)}</span></div><p>{version.previousAmount===null?"初始版本":`基准 ${formatMoney(version.previousAmount)} · 差异 ${differenceText(version.amountDifference)}`} · {version.changeReason} · 录入 {version.createdByName} · 签名 {version.signedByName??"尚未签名"}</p></li>)}</ol></section><section><h3>修改申请</h3>{data.changeRequests.length?<ol className="history-list">{data.changeRequests.map((request)=><li key={request.id}><div><strong>{request.requestedByName} · {workflowStatusName(request.status)}</strong><time>{formatOperationTime(request.createdAt)}</time></div><p>{request.reason} · 建议金额 {request.requestedAmount?formatMoney(request.requestedAmount):"未填写"} · 处理人 {request.handledByName??"尚未处理"}{request.outcomeComment?` · 意见 ${request.outcomeComment}`:""}</p></li>)}</ol>:<p>暂无修改申请。</p>}</section><section><h3>审批</h3>{data.approvals.length?<ol className="history-list">{data.approvals.map((approval)=><li key={approval.id}><div><strong>{approval.stage==="general_manager"?"总经理":"人事部"} · {approval.decision==="approved"?"批准":"拒绝"}</strong><time>{formatOperationTime(approval.decidedAt)}</time></div><p>{approval.decidedByName} · {approval.comment}</p></li>)}</ol>:<p>暂无审批记录。</p>}</section><section><h3>审计轨迹</h3><ol className="history-list">{data.audit.map((item)=><li key={item.id}><div><strong>{goalAuditName(item.action)}</strong><time>{formatOperationTime(item.createdAt)}</time></div><p>{item.actorName??"系统"} · 变更前 {auditDataText(item.beforeData)} · 变更后 {auditDataText(item.afterData)}</p></li>)}</ol></section></div>}</Modal>}

function FormalReportDialog({goal,onClose}:{goal:Goal;onClose:()=>void}){
  const[report,setReport]=useState<FormalReport|null>(null);const[error,setError]=useState("");
  useEffect(()=>{fetch(`/api/performance/formal-reports/${goal.id}`).then(async(response)=>{const data=await response.json() as FormalReport&{message?:string};if(!response.ok)throw new Error(data.message??"正式报表加载失败");setReport(data);}).catch((reason)=>setError(reason instanceof Error?reason.message:"正式报表加载失败"));},[goal.id]);
  return <Modal title="正式业绩报表" note="目标已生效，达成率按该层级目标独立计算" onClose={onClose}>{error?<p className="form-error formal-report-content">{error}</p>:report?<div className="formal-report-content"><div><span>目标月份</span><strong>{report.periodMonth}</strong></div><div><span>责任层级</span><strong>{goalLevelName(report.level)}</strong></div><div><span>生效目标</span><strong>{formatMoney(report.targetAmount)}</strong></div><div><span>实际业绩</span><strong>{formatMoney(report.actualAmount)}</strong></div><div><span>达成率</span><strong>{report.achievementRate===null?"不计算":`${report.achievementRate}%`}</strong></div><div className="modal-actions"><button type="button" onClick={()=>{window.location.href=`/api/exports/formal-reports/${goal.id}.csv`;}}>导出正式报表</button></div></div>:<p className="formal-report-content">正在计算正式报表…</p>}</Modal>;
}

function CreateGoal({user,onClose,onSaved}:{user:User;onClose:()=>void;onSaved:()=>Promise<void>}){const available:GoalLevel[]=user.roles.includes("sales_manager")?["sales_manager","department"]:user.roles.includes("sales_supervisor")?["group"]:["personal"];const[periodMonth,setPeriodMonth]=useState(businessDateToday().slice(0,7));const[level,setLevel]=useState<GoalLevel>(available[0]!);const[parentGoalId,setParentGoalId]=useState("");const[parentGoals,setParentGoals]=useState<ParentGoalOption[]>([]);const[owners,setOwners]=useState<GoalOption[]>([]);const[ownerKey,setOwnerKey]=useState("");const[amount,setAmount]=useState("");const[changeReason,setChangeReason]=useState("目标下达");const[error,setError]=useState("");const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);useEffect(()=>{const controller=new AbortController();setLoading(true);setError("");const params=new URLSearchParams({periodMonth,level});if(parentGoalId)params.set("parentGoalId",parentGoalId);fetch(`/api/goals/options?${params}`,{signal:controller.signal}).then(async(response)=>{const data=await readResponseJson<{parentGoals?:ParentGoalOption[];owners?:GoalOption[];message?:string}>(response,"目标选项响应无效，请重试。");if(!response.ok)throw new Error(data.message??"目标选项加载失败");const nextParents=data.parentGoals??[];const nextOwners=data.owners??[];setParentGoals(nextParents);setOwners(nextOwners);if(level!=="sales_manager"&&!parentGoalId&&nextParents[0]){setParentGoalId(nextParents[0].id);return;}const keys=nextOwners.map((owner)=>`${owner.personId}:${owner.orgUnitId??""}`);setOwnerKey((current)=>keys.includes(current)?current:(keys[0]??""));}).catch((failure)=>{if(failure instanceof DOMException&&failure.name==="AbortError")return;setError(failure instanceof Error?failure.message:"目标选项加载失败");}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});return()=>controller.abort();},[periodMonth,level,parentGoalId]);const selectedOwner=owners.find((owner)=>`${owner.personId}:${owner.orgUnitId??""}`===ownerKey);async function submit(event:FormEvent){event.preventDefault();if(saving)return;if(!selectedOwner||!amount||!changeReason.trim()){setError("请选择合法责任人，并填写目标金额和下达原因。");return;}setSaving(true);setError("");try{const response=await apiFetch("/api/goals",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({periodMonth,level,ownerPersonId:Number(selectedOwner.personId),orgUnitId:selectedOwner.orgUnitId?Number(selectedOwner.orgUnitId):null,parentGoalId:parentGoalId?Number(parentGoalId):null,amount:Number(amount),changeReason})});const data=await readResponseJson<{message?:string}>(response,"服务响应无效，请重试。");if(!response.ok){setError(data.message??"目标下达失败");return;}await onSaved();}catch(failure){setError(failure instanceof Error?failure.message:"网络异常，目标下达失败，请重试。");}finally{setSaving(false);}}return <Modal title="下达目标" note="责任人从当前月有效组织关系中选择；服务端再次校验直属关系" onClose={onClose}><form noValidate className="business-form" onSubmit={submit}><div className="form-grid"><Field label="目标月份" value={periodMonth} type="month" onChange={(value)=>{setPeriodMonth(value);setParentGoalId("");setOwnerKey("");}}/><label className="field"><span>目标层级</span><select value={level} onChange={(event)=>{setLevel(event.target.value as GoalLevel);setParentGoalId("");setOwnerKey("");}}>{available.map((item)=><option key={item} value={item}>{goalLevelName(item)}</option>)}</select></label>{level!=="sales_manager"?<label className="field"><span>直属上级目标</span><select value={parentGoalId} onChange={(event)=>{setParentGoalId(event.target.value);setOwnerKey("");}}><option value="">请选择已生效的直属上级目标</option>{parentGoals.map((parent)=><option key={parent.id} value={parent.id}>{parent.ownerName} · {parent.orgUnitName??goalLevelName(level)} · {formatMoney(parent.amount)}</option>)}</select></label>:null}<label className="field"><span>目标责任人</span><select value={ownerKey} disabled={loading||owners.length===0} onChange={(event)=>setOwnerKey(event.target.value)}><option value="">{loading?"正在加载合法责任人…":"请选择责任人"}</option>{owners.map((owner)=><option key={`${owner.personId}:${owner.orgUnitId??""}`} value={`${owner.personId}:${owner.orgUnitId??""}`}>{owner.name}{owner.orgUnitName?` · ${owner.orgUnitName}`:""}</option>)}</select></label><Field label="目标金额" value={amount} type="number" onChange={setAmount}/><Field label="下达原因" value={changeReason} onChange={setChangeReason}/></div>{level!=="sales_manager"&&parentGoals.length===0&&!loading?<p className="form-note">当前月份没有可用的已生效直属上级目标，请先完成上一级审批。</p>:null}{error?<p className="form-error" role="alert">{error}</p>:null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit" disabled={saving||loading} aria-busy={saving}>{saving?"正在提交…":"提交待确认"}</button></div></form></Modal>}

function Overview({ canEdit, canExport, onEnterOrders }: { canEdit: boolean; canExport: boolean; onEnterOrders: () => void }) {
  const [data, setData] = useState<DashboardData | null>(null);
  const [showPersonalDetails,setShowPersonalDetails]=useState(false);
  const [personalDetailKind,setPersonalDetailKind]=useState<"actual"|"gap">("actual");
  const [personalDetails,setPersonalDetails]=useState<PersonalAchievementDrilldown|null>(null);
  const [personalDetailsError,setPersonalDetailsError]=useState("");
  const [selectedGroup,setSelectedGroup]=useState<GroupAchievement|null>(null);
  const [groupDetailKind,setGroupDetailKind]=useState<"actual"|"gap">("actual");
  const [groupDetails,setGroupDetails]=useState<GroupAchievementDrilldown|null>(null);
  const [groupDetailsError,setGroupDetailsError]=useState("");
  useEffect(() => { fetch("/api/performance/dashboard").then(async (response) => { if (!response.ok) throw new Error("总览加载失败"); setData(await response.json() as DashboardData); }).catch(() => setData(null)); }, []);
  const maxGroup = Math.max(1, ...(data?.groups.map((group) => Number(group.total)) ?? [1]));
  const personal=data?.personalAchievement;
  const reasonText=(value:PersonalAchievement["calculationReason"],scope:string)=>value===null?null:({PERIOD_IN_FUTURE:"未来月份不计算目标达成",TARGET_NOT_ACTIVE:`${scope}目标尚未生效`,TARGET_AMOUNT_NOT_POSITIVE:"生效目标金额必须大于零"} as const)[value];
  const reason=personal?reasonText(personal.calculationReason,"个人"):null;
  async function openPersonalDetails(kind:"actual"|"gap"){if(!personal)return;setPersonalDetailKind(kind);setShowPersonalDetails(true);setPersonalDetails(null);setPersonalDetailsError("");try{const response=await fetch(`/api/performance/personal-achievement/events?month=${personal.periodMonth}`);const result=await readResponseJson<PersonalAchievementDrilldown&{message?:string}>(response,"个人业绩构成响应无效");if(!response.ok)throw new Error(result.message??"个人业绩构成加载失败");const{events,...achievement}=result;if(kind==="gap"&&result.gapAmount===null)setPersonalDetailKind("actual");setPersonalDetails(result);setData((current)=>current?{...current,personalAchievement:achievement}:current);}catch(error){setPersonalDetailsError(error instanceof Error?error.message:"个人业绩构成加载失败");}}
  async function openGroupDetails(group:GroupAchievement,kind:"actual"|"gap"){setSelectedGroup(group);setGroupDetailKind(kind);setGroupDetails(null);setGroupDetailsError("");try{const response=await fetch(`/api/performance/group-achievement/events?month=${group.periodMonth}&groupId=${group.groupId}`);const result=await readResponseJson<GroupAchievementDrilldown&{message?:string}>(response,"小组业绩构成响应无效");if(!response.ok)throw new Error(result.message??"小组业绩构成加载失败");const{members,...achievement}=result;if(kind==="gap"&&result.gapAmount===null)setGroupDetailKind("actual");setGroupDetails(result);setData((current)=>current?{...current,groupAchievements:current.groupAchievements.map((item)=>item.groupId===result.groupId?achievement:item)}:current);}catch(error){setGroupDetailsError(error instanceof Error?error.message:"小组业绩构成加载失败");}}
  return <main className="dashboard"><header><div><h1>业绩账本总览</h1><p>{data ? `${data.month.replace("-", " 年 ")} 月 · ${personal?"个人目标与不可变业绩事件":"原始账本，不代表正式绩效结果"}` : "正在加载真实业绩账本…"}</p></div><div className="header-actions">{canExport?<button className="secondary-action" onClick={()=>{window.location.href="/api/exports/performance.csv"}}>导出业绩流水</button>:null}{canEdit?<button className="primary-action" onClick={onEnterOrders}>录入订单业绩</button>:null}</div></header>
      {personal?<><section className="metric-band personal-metrics" aria-label="个人目标达成"><Metric label="生效目标" value={personal.targetAmount===null?"—":formatMoney(personal.targetAmount)} note={reason??"当前月个人目标"}/><Metric label="个人业绩" value={formatMoney(personal.actualAmount)} note={`${personal.eventCount} 条本人事件`} onClick={()=>openPersonalDetails("actual")} actionLabel="查看个人业绩构成"/><Metric label="差距" value={personal.gapAmount===null?"不计算":formatMoney(personal.gapAmount)} note={reason??"生效目标减个人业绩"} onClick={personal.gapAmount===null?undefined:()=>openPersonalDetails("gap")} actionLabel={personal.gapAmount===null?undefined:"查看个人差距构成"}/><Metric label="达成率" value={personal.achievementRate===null?"不计算":`${personal.achievementRate}%`} note={reason??"个人业绩 ÷ 生效目标"}/><Metric label="自然日进度" value={personal.timeProgressRate===null?"不计算":`${personal.timeProgressRate}%`} note={reason??"按上海自然日计算"}/><Metric label="进度偏差" value={personal.progressVariance===null?"不计算":`${personal.progressVariance}%`} note={reason??"达成率减自然日进度"} warning={personal.progressVariance!==null&&Number(personal.progressVariance)<0}/></section>{showPersonalDetails?<Modal title={personalDetailKind==="gap"?"个人差距构成":"个人业绩构成"} note={personalDetails?(personalDetailKind==="gap"?`目标 ${formatMoney(personalDetails.targetAmount!)} − 事件净额 ${formatMoney(personalDetails.actualAmount)} = 差距 ${formatMoney(personalDetails.gapAmount!)}`:`${personalDetails.events.length} 条事件 · 净额 ${formatMoney(personalDetails.actualAmount)}`):`正在读取 ${personal.periodMonth} 个人业绩事件`} onClose={()=>setShowPersonalDetails(false)}>{personalDetailsError?<p className="form-error personal-drilldown" role="alert">{personalDetailsError}</p>:personalDetails?<div className="personal-drilldown"><div className="orders-table-wrap"><table><thead><tr><th>订单</th><th>客户</th><th>不可变事件</th><th>业务日 / 记账月</th><th>金额方向</th><th>状态 / 计入</th><th>组织归属</th><th>订单当前分析资料</th><th>原因</th></tr></thead><tbody>{personalDetails.events.map((event)=><tr key={event.id}><td>{event.orderNo}</td><td>{event.customerName}</td><td>{eventTypeName(event.eventType)} · 第 {event.sequence} 条</td><td>{event.occurredOn} / {event.accountingMonth}</td><td className={event.deltaAmount.startsWith("-")?"negative":""}>{event.deltaAmount.startsWith("-")?"负向":"正向"} {formatMoney(event.deltaAmount.startsWith("-")?event.deltaAmount.slice(1):event.deltaAmount)}</td><td>{event.resultingLifecycleState?<><Status state={event.resultingLifecycleState}/><small className="table-secondary">计入至 {formatMoney(event.resultingCountedAmount)}</small></>:"原始状态未推断"}</td><td>{[event.departmentName,event.groupName].filter(Boolean).join(" / ")||"—"}</td><td>分析维度待补齐</td><td>{event.reason??"—"}</td></tr>)}</tbody></table></div>{personalDetails.events.length===0?<p className="empty-cell">当前月份没有个人业绩事件。</p>:null}</div>:<p className="personal-drilldown">正在读取个人业绩构成…</p>}</Modal>:null}</>:null}
      {data?.groupAchievements.map((group)=>{const groupReason=reasonText(group.calculationReason,"小组");return <article className="team-achievement orders-card" aria-label={`${group.groupName}目标达成`} key={group.groupId}><PanelTitle title={`小组目标达成 · ${group.groupName}`} note={`${group.memberCount} 位事件责任人 · 按事件发生时组织归属`}/><section className="metric-band personal-metrics"><Metric label="小组生效目标" value={group.targetAmount===null?"—":formatMoney(group.targetAmount)} note={groupReason??"当前月小组目标"}/><Metric label="小组业绩" value={formatMoney(group.actualAmount)} note={`${group.eventCount} 条小组事件`} onClick={()=>openGroupDetails(group,"actual")} actionLabel={`查看${group.groupName}业绩构成`}/><Metric label="小组差距" value={group.gapAmount===null?"不计算":formatMoney(group.gapAmount)} note={groupReason??"生效目标减小组业绩"} onClick={group.gapAmount===null?undefined:()=>openGroupDetails(group,"gap")} actionLabel={group.gapAmount===null?undefined:`查看${group.groupName}差距构成`}/><Metric label="小组达成率" value={group.achievementRate===null?"不计算":`${group.achievementRate}%`} note={groupReason??"小组业绩 ÷ 生效目标"}/><Metric label="自然日进度" value={group.timeProgressRate===null?"不计算":`${group.timeProgressRate}%`} note={groupReason??"按上海自然日计算"}/><Metric label="进度偏差" value={group.progressVariance===null?"不计算":`${group.progressVariance}%`} note={groupReason??"达成率减自然日进度"} warning={group.progressVariance!==null&&Number(group.progressVariance)<0}/></section></article>})}
      {selectedGroup?<Modal title={`${selectedGroup.groupName} · ${groupDetailKind==="gap"?"小组差距构成":"小组业绩构成"}`} note={groupDetails?(groupDetailKind==="gap"?`目标 ${formatMoney(groupDetails.targetAmount!)} − 事件净额 ${formatMoney(groupDetails.actualAmount)} = 差距 ${formatMoney(groupDetails.gapAmount!)}`:`${groupDetails.memberCount} 位事件责任人 · ${groupDetails.eventCount} 条事件 · 净额 ${formatMoney(groupDetails.actualAmount)}`):`正在读取 ${selectedGroup.groupName} 小组业绩事件`} onClose={()=>setSelectedGroup(null)}>{groupDetailsError?<p className="form-error group-drilldown" role="alert">{groupDetailsError}</p>:groupDetails?<div className="group-drilldown">{groupDetails.members.map((member)=><section className="orders-card group-member" key={member.personId}><PanelTitle title={member.name} note={`${member.orders.length} 笔订单 · ${member.eventCount} 条事件 · 净额 ${formatMoney(member.actualAmount)}`}/>{member.orders.map((order)=><div className="group-order" key={order.orderId}><h4>{order.orderNo} · {order.customerName}<small>{order.eventCount} 条事件 · 净额 {formatMoney(order.actualAmount)}</small></h4><div className="orders-table-wrap"><table><thead><tr><th>不可变事件</th><th>业务日 / 记账月</th><th>金额方向</th><th>状态 / 计入</th><th>组织归属</th><th>分析维度</th><th>原因</th></tr></thead><tbody>{order.events.map((event)=><tr key={event.id}><td>{eventTypeName(event.eventType)} · 第 {event.sequence} 条</td><td>{event.occurredOn} / {event.accountingMonth}</td><td className={event.deltaAmount.startsWith("-")?"negative":""}>{event.deltaAmount.startsWith("-")?"负向":"正向"} {formatMoney(event.deltaAmount.startsWith("-")?event.deltaAmount.slice(1):event.deltaAmount)}</td><td>{event.resultingLifecycleState?<><Status state={event.resultingLifecycleState}/><small className="table-secondary">计入至 {formatMoney(event.resultingCountedAmount)}</small></>:"原始状态未推断"}</td><td>{[event.departmentName,event.groupName].filter(Boolean).join(" / ")||"—"}</td><td>待补齐</td><td>{event.reason??"—"}</td></tr>)}</tbody></table></div></div>)}</section>)}</div>:<p className="group-drilldown">正在读取小组业绩构成…</p>}</Modal>:null}
      <section className="metric-band"><Metric label="账本净额" value={data ? formatMoney(data.metrics.total) : "—"} note={`${data?.metrics.eventCount ?? 0} 条授权范围事件`}/><Metric label="正式报表" value="从生效目标进入" note="未生效不计算达成率"/><Metric label="待处理审批" value={String(data?.metrics.pendingApprovals ?? 0)} note="目标确认与变更" warning/><Metric label="负向调整" value={data ? formatMoney(data.metrics.negativeTotal) : "—"} note="暂停与金额变更" negative/></section>
      <section className="dashboard-grid"><article className="trend-panel"><PanelTitle title="月度业绩趋势" note={`${data?.month.slice(0,4)??"当前"} 年授权范围业绩净额`}/><TrendChart year={data?.month.slice(0,4)??""} monthly={data?.monthly??[]}/></article><article className="ranking-panel"><PanelTitle title="小组业绩" note="按事件发生时组织归属"/>{data?.groups.map((group,i) => <div className="rank-row" key={group.name}><span>{i+1}</span><div><strong>{group.name}</strong><span><i style={{width:`${Math.max(0, Number(group.total)) / maxGroup * 100}%`}}/></span></div><b>{(Number(group.total)/10000).toFixed(1)}万</b></div>)}</article></section>
      <section className="events-panel"><div className="panel-title"><div><h2>最近业绩事件</h2><p>入账后不可覆盖或删除</p></div><button onClick={onEnterOrders}>查看全部</button></div><table><thead><tr><th>订单编号</th><th>业务员</th><th>事件类型</th><th>记账月</th><th>金额</th><th>组织归属</th><th>状态</th></tr></thead><tbody>{data?.recent.map((event) => <tr key={`${event.orderNo}-${event.month}-${event.amount}`}><td>{event.orderNo}</td><td>{event.salespersonName}</td><td>{eventTypeName(event.eventType)}</td><td>{event.month}</td><td className={Number(event.amount)<0?"negative":""}>{formatMoney(event.amount)}</td><td>{event.groupName}</td><td>已入账</td></tr>)}</tbody></table></section>
    </main>;
}

function OrdersPage({ user }: { user: User }) {
  const canEdit=user.capabilities.editPerformance;
  const [orders, setOrders] = useState<Order[]>([]);
  const [selected, setSelected] = useState<Order | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [message, setMessage] = useState("");
  const initialSearch = new URLSearchParams(window.location.search).get("orderSearch") ?? "";
  const [search, setSearch] = useState(initialSearch);
  const [committedSearch, setCommittedSearch] = useState(initialSearch);
  const [isComposing, setIsComposing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [refreshVersion, setRefreshVersion] = useState(0);
  const searchRef = useRef<HTMLInputElement>(null);
  const commitSearch = useCallback((value:string, historyMode:"push"|"replace"="push") => {
    const normalized=value.trim();
    const params=new URLSearchParams(window.location.search);
    if(normalized)params.set("orderSearch",normalized);else params.delete("orderSearch");
    const next=`${window.location.pathname}${params.size?`?${params.toString()}`:""}${window.location.hash}`;
    window.history[historyMode==="push"?"pushState":"replaceState"]({},"",next);
    setCommittedSearch(normalized);
  },[]);
  useEffect(()=>{
    const restore=()=>{const value=new URLSearchParams(window.location.search).get("orderSearch")??"";setSearch(value);setCommittedSearch(value);};
    window.addEventListener("popstate",restore);return()=>window.removeEventListener("popstate",restore);
  },[]);
  useEffect(()=>{
    if(isComposing||search.trim()===committedSearch)return;
    const timer=window.setTimeout(()=>commitSearch(search),300);
    return()=>window.clearTimeout(timer);
  },[search,isComposing,committedSearch,commitSearch]);
  useEffect(() => {
    const controller=new AbortController();setLoading(true);setMessage("");
    const params=new URLSearchParams({limit:"100"});if(committedSearch)params.set("search",committedSearch);
    fetch(`/api/performance/orders?${params.toString()}`,{signal:controller.signal}).then(async(response)=>{
      const data=await response.json() as {orders?:Order[];message?:string};
      if(!response.ok)throw new Error(data.message??"订单加载失败");
      setOrders(data.orders??[]);
    }).catch((error)=>{if(error instanceof DOMException&&error.name==="AbortError")return;setMessage(error instanceof Error?error.message:"订单加载失败");})
      .finally(()=>{if(!controller.signal.aborted)setLoading(false);});
    return()=>controller.abort();
  }, [committedSearch,refreshVersion]);
  async function refresh() { setRefreshVersion((value)=>value+1); }
  function clearSearch(){setSearch("");commitSearch("");window.requestAnimationFrame(()=>searchRef.current?.focus());}
  return <main className="dashboard orders-page"><header><div><h1>订单业绩</h1><p>按订单编号维护不可变业绩事件；已入账记录不能覆盖或删除</p></div>{canEdit ? <div className="header-actions"><button className="secondary-action" onClick={() => setShowImport(true)}><FileUp size={16}/>Excel 导入</button><button className="primary-action" onClick={() => setShowCreate(true)}><Plus size={16}/>录入新订单</button></div> : null}</header>
    {message ? <p className="page-message" role="status">{message}</p> : null}
    {!canEdit ? <div className="permission-note"><ShieldCheck size={18}/>当前角色仅可查看。只有销售助理及销售助理组长可以录入或调整业绩。</div> : null}
    <LedgerGovernancePanel user={user} orders={orders} onChanged={refresh}/>
    <section className="orders-card" aria-labelledby="orders-table-title"><div className="orders-toolbar"><div><h2 id="orders-table-title">订单台账</h2><span role="status">{loading?"正在查询…":`${orders.length} 笔订单`}</span></div><button className="icon-action" onClick={() => refresh()} aria-label="刷新订单"><RefreshCw size={17}/></button></div>
      <form className="order-search" role="search" noValidate onSubmit={(event)=>{event.preventDefault();if(!isComposing)commitSearch(search);}}><label htmlFor="order-search-input">定位订单</label><div><Search size={17} aria-hidden="true"/><input ref={searchRef} id="order-search-input" type="search" value={search} placeholder="输入订单编号、客户或业务员" onChange={(event)=>setSearch(event.target.value)} onCompositionStart={()=>setIsComposing(true)} onCompositionEnd={(event)=>{setIsComposing(false);setSearch(event.currentTarget.value);}}/>{search?<button type="button" onClick={clearSearch} aria-label="清除订单搜索"><X size={16}/></button>:null}</div><button type="submit">搜索</button></form>
      <div className="orders-table-wrap"><table><thead><tr><th scope="col">订单编号</th><th scope="col">客户</th><th scope="col">业务员</th><th scope="col">当前营业额</th><th scope="col">计入业绩</th><th scope="col">状态</th><th scope="col">操作</th></tr></thead><tbody>{!loading&&orders.length === 0 ? <tr><td colSpan={7} className="empty-cell">{committedSearch?`没有找到与“${committedSearch}”匹配的订单。`:"暂无订单，请录入第一笔业绩。"}</td></tr> : orders.map((order) => <tr key={order.id}><td>{order.orderNo}</td><td>{order.customerName}</td><td>{order.salespersonName}</td><td>{formatMoney(order.currentRevenue)}</td><td>{formatMoney(order.countedAmount)}</td><td><Status state={order.lifecycleState}/></td><td><button className="table-action" onClick={() => setSelected(order)}>查看 / 调整</button></td></tr>)}</tbody></table></div>
    </section>
    {showCreate ? <CreateOrder onClose={() => setShowCreate(false)} onSaved={async () => { setShowCreate(false); await refresh(); }} /> : null}
    {showImport ? <ExcelImportDialog user={user} onClose={() => setShowImport(false)} onImported={async () => { setShowImport(false); await refresh(); }} /> : null}
    {selected ? <AdjustOrder order={selected} canEdit={canEdit} onClose={() => setSelected(null)} onSaved={async () => { setSelected(null); await refresh(); }} /> : null}
  </main>;
}

type ImportConfig = { id:string; name:string; version:number; status:"draft"|"approved"|"retired"; sheetName:string };
type ImportIssue = { rowNumber:number; code:string; severity:"blocking"|"warning"|"info"; message:string };
type ImportReconciliationSummary = { rows:number; orders:number; events:number; totalAmount:number; monthly:Array<{month:string;events:number;totalAmount:number}> };
type ImportReport = { batchId:string; status:"blocked"|"preflight_ready"; sourceSha256:string; issues:ImportIssue[]; summary:{rows:number;orders:number;events:number;totalAmount:number;blocking:number;warnings:number}; reconciliation:{actual:ImportReconciliationSummary;expected:ImportReconciliationSummary|null;matched:boolean|null} };

function fileAsBase64(file:File):Promise<string>{return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error("文件读取失败，请重新选择。"));reader.onload=()=>{const result=String(reader.result??"");const comma=result.indexOf(",");if(comma<0){reject(new Error("文件内容无效。"));return;}resolve(result.slice(comma+1));};reader.readAsDataURL(file);});}

function ExcelImportDialog({user,onClose,onImported}:{user:User;onClose:()=>void;onImported:()=>Promise<void>}){
  const[configs,setConfigs]=useState<ImportConfig[]>([]);const[configId,setConfigId]=useState("");const[file,setFile]=useState<File|null>(null);const[report,setReport]=useState<ImportReport|null>(null);const[confirmedWarnings,setConfirmedWarnings]=useState<Set<string>>(new Set());const[error,setError]=useState("");const[loading,setLoading]=useState(true);const[busy,setBusy]=useState(false);const isLeader=user.roles.includes("sales_assistant_leader");
  useEffect(()=>{const controller=new AbortController();fetch("/api/imports/configs",{signal:controller.signal}).then(async(response)=>{const data=await response.json() as {configs?:ImportConfig[];message?:string};if(!response.ok)throw new Error(data.message??"导入配置加载失败");const approved=(data.configs??[]).filter((item)=>item.status==="approved");setConfigs(approved);setConfigId(approved[0]?.id??"");}).catch((failure)=>{if(failure instanceof DOMException&&failure.name==="AbortError")return;setError(failure instanceof Error?failure.message:"导入配置加载失败");}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});return()=>controller.abort();},[]);
  function chooseFile(selected:File|null){setReport(null);setConfirmedWarnings(new Set());setError("");if(!selected){setFile(null);return;}if(!selected.name.toLowerCase().endsWith(".xlsx")){setFile(null);setError("只接受 .xlsx 工作簿。");return;}if(selected.size===0||selected.size>20*1024*1024){setFile(null);setError("文件必须大于 0 且不超过 20 MB。");return;}setFile(selected);}
  async function preflight(event:FormEvent){event.preventDefault();if(busy)return;if(!configId||!file){setError("请选择已批准的导入配置和一个 .xlsx 文件。");return;}setBusy(true);setError("");setReport(null);try{const contentBase64=await fileAsBase64(file);const response=await apiFetch("/api/imports/preflight",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({configId:Number(configId),fileName:file.name,contentBase64})});const data=await response.json() as ImportReport&{message?:string};if(!response.ok)throw new Error(data.message??"预检失败");setReport(data);}catch(failure){setError(failure instanceof Error?failure.message:"预检失败，请重试。");}finally{setBusy(false);}}
  async function confirm(){if(!report||busy)return;setBusy(true);setError("");try{const response=await apiFetch(`/api/imports/batches/${report.batchId}/confirm`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({confirmedWarnings:[...confirmedWarnings]})});const data=await response.json() as {message?:string};if(!response.ok)throw new Error(data.message??"确认入账失败");await onImported();}catch(failure){setError(failure instanceof Error?failure.message:"确认入账失败，请重试。");}finally{setBusy(false);}}
  const warningKeys=report?.issues.filter((issue)=>issue.severity==="warning").map((issue)=>`${issue.rowNumber}:${issue.code}`)??[];const allWarningsConfirmed=warningKeys.every((key)=>confirmedWarnings.has(key));
  return <Modal title="Excel 批量导入" note="先完整预检，只有销售助理组长可以把无阻断批次原子入账" onClose={onClose}><form noValidate className="business-form import-form" onSubmit={preflight}><div className="import-guidance"><a href="/SampleFlow标准业绩导入模板.xlsx" download>下载标准业绩模板</a><span>仅接收固定值 .xlsx；公式、宏、外部链接和未知表头会被阻断。</span></div><label className="field"><span>已批准导入配置</span><select value={configId} disabled={loading||busy} onChange={(event)=>{setConfigId(event.target.value);setReport(null);}}><option value="">{loading?"正在加载…":"请选择"}</option>{configs.map((item)=><option key={item.id} value={item.id}>{item.name} · v{item.version}</option>)}</select></label><label className="import-file"><FileUp size={22}/><span>{file?file.name:"选择一个 .xlsx 文件"}</span><small>{file?`${(file.size/1024).toFixed(1)} KB`:"单文件上限 20 MB；不会显示或记录本地路径"}</small><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" disabled={busy} onChange={(event)=>chooseFile(event.currentTarget.files?.[0]??null)}/></label>{!loading&&configs.length===0?<p className="permission-note">暂无已批准配置。销售助理组长需先创建草稿，并由人事批准业务区域及人员精确映射。</p>:null}{error?<p className="form-error" role="alert">{error}</p>:null}{report?<section className={`import-report import-${report.status}`} aria-labelledby="import-report-title"><h3 id="import-report-title">{report.status==="blocked"?"预检未通过":"预检通过，等待确认"}</h3><dl><div><dt>来源 SHA-256</dt><dd>{report.sourceSha256}</dd></div><div><dt>来源行 / 订单 / 待入账事件</dt><dd>{report.summary.rows} / {report.summary.orders} / {report.summary.events}</dd></div><div><dt>金额合计</dt><dd>{formatMoney(report.summary.totalAmount)}</dd></div><div><dt>阻断 / 警告</dt><dd>{report.summary.blocking} / {report.summary.warnings}</dd></div></dl><div className="import-reconciliation"><h4>逐月对账</h4><div className="orders-table-wrap"><table><thead><tr><th>月份</th><th>实际事件</th><th>实际金额</th><th>预期事件</th><th>预期金额</th></tr></thead><tbody>{report.reconciliation.actual.monthly.map((month)=>{const expected=report.reconciliation.expected?.monthly.find((item)=>item.month===month.month);return <tr key={month.month}><td>{month.month}</td><td>{month.events}</td><td>{formatMoney(month.totalAmount)}</td><td>{expected?.events??"—"}</td><td>{expected?formatMoney(expected.totalAmount):"—"}</td></tr>;})}</tbody></table></div><p>{report.reconciliation.matched===true?"整体与逐月对账一致。":report.reconciliation.matched===false?"整体或逐月对账不一致，批次已阻断。":"当前配置未设置预期基准，仅展示实际逐月汇总。"}</p></div>{report.issues.length?<ul>{report.issues.map((issue,index)=>{const warningKey=`${issue.rowNumber}:${issue.code}`;const issueLabel=issue.severity==="blocking"?"阻断":issue.severity==="warning"?"警告":"提示";return <li key={`${warningKey}-${index}`}><strong>{issue.rowNumber===0?"批次级":`第 ${issue.rowNumber} 行`} · {issueLabel}</strong><span>{issue.message}</span>{issue.severity==="warning"?<label><input type="checkbox" checked={confirmedWarnings.has(warningKey)} onChange={(event)=>setConfirmedWarnings((current)=>{const next=new Set(current);if(event.target.checked)next.add(warningKey);else next.delete(warningKey);return next;})}/>我已核对并确认此条警告</label>:null}</li>;})}</ul>:<p>未发现阻断、警告或提示。</p>}</section>:null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button>{!report?<button type="submit" disabled={busy||loading||!file||!configId} aria-busy={busy}>{busy?"正在预检…":"运行只读预检"}</button>:report.status==="preflight_ready"&&isLeader?<button type="button" className="import-confirm" disabled={busy||!allWarningsConfirmed} aria-busy={busy} onClick={confirm}>{busy?"正在原子入账…":"确认整批入账"}</button>:report.status==="preflight_ready"?<span className="import-handoff">请交由销售助理组长确认入账</span>:<button type="button" onClick={()=>setReport(null)}>重新选择</button>}</div></form></Modal>;
}

const standardBusinessRegions = [
  ["CN-BJ","北京市"],["CN-TJ","天津市"],["CN-HE","河北省"],["CN-SX","山西省"],["CN-NM","内蒙古自治区"],
  ["CN-LN","辽宁省"],["CN-JL","吉林省"],["CN-HL","黑龙江省"],["CN-SH","上海市"],["CN-JS","江苏省"],
  ["CN-ZJ","浙江省"],["CN-AH","安徽省"],["CN-FJ","福建省"],["CN-JX","江西省"],["CN-SD","山东省"],
  ["CN-HA","河南省"],["CN-HB","湖北省"],["CN-HN","湖南省"],["CN-GD","广东省"],["CN-GX","广西壮族自治区"],
  ["CN-HI","海南省"],["CN-CQ","重庆市"],["CN-SC","四川省"],["CN-GZ","贵州省"],["CN-YN","云南省"],
  ["CN-XZ","西藏自治区"],["CN-SN","陕西省"],["CN-GS","甘肃省"],["CN-QH","青海省"],["CN-NX","宁夏回族自治区"],
  ["CN-XJ","新疆维吾尔自治区"],
  ["EXT-TRADE","外贸"],
] as const;

const initialOrder = { orderNo: "", customerName: "", customerUnit: "", businessRegionCode: "", salespersonPersonId: "", serviceType: "", sourceReceivedOn: businessDateToday(), amount: "", reason: "首次录入" };

function previousBusinessMonth():string{const [year,month]=businessDateToday().slice(0,7).split("-").map(Number);return new Date(Date.UTC(year!,month!-2,1)).toISOString().slice(0,7);}

function LedgerGovernancePanel({user,orders,onChanged}:{user:User;orders:Order[];onChanged:()=>Promise<void>}){
  const isLeader=user.roles.includes("sales_assistant_leader");
  const isHr=user.roles.includes("hr");
  const[periods,setPeriods]=useState<AccountingPeriod[]>([]);
  const[corrections,setCorrections]=useState<AccountingCorrection[]>([]);
  const[reviews,setReviews]=useState<HistoricalReview[]>([]);
  const[month,setMonth]=useState(previousBusinessMonth());
  const[periodNote,setPeriodNote]=useState("");
  const[decisionNote,setDecisionNote]=useState("");
  const[message,setMessage]=useState("");
  const[busy,setBusy]=useState(false);
  const[correction,setCorrection]=useState({orderId:"",eventType:"revenue_change",occurredOn:`${previousBusinessMonth()}-01`,reason:""});
  const[review,setReview]=useState({orderId:"",lifecycleState:"active",currentRevenue:"",conclusion:"",evidence:"",reason:""});
  const[execution,setExecution]=useState<AccountingCorrection|null>(null);
  const[executionAmount,setExecutionAmount]=useState("");
  const[executionReason,setExecutionReason]=useState("");
  const load=useCallback(async()=>{
    if(!isLeader&&!isHr)return;
    const responses=await Promise.all([fetch("/api/accounting-periods"),fetch("/api/accounting-corrections"),fetch("/api/historical-order-reviews")]);
    const data=await Promise.all(responses.map((response)=>response.json()));
    const failed=responses.findIndex((response)=>!response.ok);
    if(failed>=0)throw new Error((data[failed] as {message?:string}).message??"账本治理数据加载失败");
    setPeriods((data[0] as {periods:AccountingPeriod[]}).periods??[]);
    setCorrections((data[1] as {corrections:AccountingCorrection[]}).corrections??[]);
    setReviews((data[2] as {reviews:HistoricalReview[]}).reviews??[]);
  },[isHr,isLeader]);
  useEffect(()=>{load().catch((error)=>setMessage(error instanceof Error?error.message:"账本治理数据加载失败"));},[load]);
  useEffect(()=>{if(orders[0]){setCorrection((current)=>current.orderId?current:{...current,orderId:orders[0]!.id});setReview((current)=>current.orderId?current:{...current,orderId:orders[0]!.id});}},[orders]);
  if(!isLeader&&!isHr)return null;
  async function post(url:string,payload:unknown){
    setBusy(true);setMessage("");
    try{const response=await apiFetch(url,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const data=await response.json() as {message?:string};if(!response.ok)throw new Error(data.message??"操作失败");await load();await onChanged();setMessage("操作已记录并刷新。");return true;}
    catch(error){setMessage(error instanceof Error?error.message:"操作失败");return false;}
    finally{setBusy(false);}
  }
  async function submitCorrection(event:FormEvent){event.preventDefault();const ok=await post("/api/accounting-corrections",{periodMonth:month,orderId:Number(correction.orderId),eventType:correction.eventType,occurredOn:correction.occurredOn,reason:correction.reason});if(ok)setCorrection((current)=>({...current,reason:""}));}
  async function submitReview(event:FormEvent){event.preventDefault();const ok=await post("/api/historical-order-reviews",{orderId:Number(review.orderId),lifecycleState:review.lifecycleState,currentRevenue:Number(review.currentRevenue),conclusion:review.conclusion,evidence:review.evidence,reason:review.reason});if(ok)setReview((current)=>({...current,currentRevenue:"",conclusion:"",evidence:"",reason:""}));}
  async function executeCorrection(event:FormEvent){event.preventDefault();if(!execution)return;const payload={type:execution.eventType,reason:executionReason,idempotencyKey:crypto.randomUUID(),correctionRequestId:Number(execution.id),...(execution.eventType==="revenue_change"?{newAmount:Number(executionAmount)}:{}),...(execution.eventType==="first_include"?{amount:Number(executionAmount)}:{})};const ok=await post(`/api/performance/orders/${execution.orderId}/events`,payload);if(ok){setExecution(null);setExecutionAmount("");setExecutionReason("");}}
  const reviewableOrders=orders.filter((order)=>order.lifecycleState==="historical_review_required");
  return <section className="governance-card" aria-labelledby="ledger-governance-title"><div className="orders-toolbar"><div><h2 id="ledger-governance-title">记账治理工作台</h2><span>关账、更正与历史核对均保留职责分离和审计</span></div><button className="icon-action" onClick={()=>load().catch((error)=>setMessage(error instanceof Error?error.message:"刷新失败"))} aria-label="刷新记账治理"><RefreshCw size={17}/></button></div>
    {message?<p className="page-message" role="status">{message}</p>:null}
    <div className="governance-grid"><form noValidate onSubmit={(event)=>event.preventDefault()}><h3>{isLeader&&isHr?"期间核对与关账":isHr?"人事关账":"组长核对确认"}</h3><label className="field"><span>记账月份</span><input type="month" value={month} onChange={(event)=>{setMonth(event.target.value);setCorrection((current)=>({...current,occurredOn:`${event.target.value}-01`}));}}/></label><Field label={isLeader&&isHr?"核对或关账说明":isHr?"关账说明":"核对说明"} value={periodNote} onChange={setPeriodNote}/>{isLeader?<button type="button" disabled={busy} onClick={()=>post(`/api/accounting-periods/${month}/confirm-close`,{note:periodNote})}>提交核对确认</button>:null}{isHr?<button type="button" disabled={busy} onClick={()=>post(`/api/accounting-periods/${month}/close`,{note:periodNote})}>关闭记账期间</button>:null}</form>
      {isLeader?<form noValidate onSubmit={submitCorrection}><h3>申请关闭月更正</h3><OrderSelect orders={orders} value={correction.orderId} onChange={(orderId)=>setCorrection((current)=>({...current,orderId}))}/><label className="field"><span>更正类型</span><select value={correction.eventType} onChange={(event)=>setCorrection((current)=>({...current,eventType:event.target.value}))}><option value="revenue_change">营业额修改</option><option value="pause">整单暂停</option><option value="restart">订单重启</option><option value="first_include">首次计入</option></select></label><Field label="原业务日期" type="date" value={correction.occurredOn} onChange={(occurredOn)=>setCorrection((current)=>({...current,occurredOn}))}/><Field label="申请原因" value={correction.reason} onChange={(reason)=>setCorrection((current)=>({...current,reason}))}/><button type="submit" disabled={busy}>提交更正申请</button></form>:null}
      {isLeader?<form noValidate onSubmit={submitReview}><h3>提交历史订单核对</h3><OrderSelect orders={reviewableOrders} value={review.orderId} onChange={(orderId)=>setReview((current)=>({...current,orderId}))}/><label className="field"><span>核对后状态</span><select value={review.lifecycleState} onChange={(event)=>setReview((current)=>({...current,lifecycleState:event.target.value}))}><option value="active">正向计入</option><option value="paused">已暂停</option><option value="zero">零金额</option></select></label><Field label="核对后当前营业额" type="number" value={review.currentRevenue} onChange={(currentRevenue)=>setReview((current)=>({...current,currentRevenue}))}/><Field label="核对结论" value={review.conclusion} onChange={(conclusion)=>setReview((current)=>({...current,conclusion}))}/><Field label="核对依据" value={review.evidence} onChange={(evidence)=>setReview((current)=>({...current,evidence}))}/><Field label="核对原因" value={review.reason} onChange={(reason)=>setReview((current)=>({...current,reason}))}/><button type="submit" disabled={busy||!reviewableOrders.length}>提交人事审批</button></form>:null}</div>
    {isHr?<label className="field governance-decision"><span>审批意见</span><input value={decisionNote} onChange={(event)=>setDecisionNote(event.target.value)} placeholder="批准、驳回或撤销前填写"/></label>:null}
    <div className="governance-lists"><div><h3>记账期间</h3>{periods.length?<ul>{periods.map((period)=><li key={period.periodMonth}><strong>{period.periodMonth.slice(0,7)}</strong><span>{period.status==="closed"?`已关闭 · 版本 ${period.version}`:"开放"}{period.needsReclose?" · 待重新关账":""}</span></li>)}</ul>:<p>尚无期间治理记录。</p>}</div><div><h3>更正申请</h3>{corrections.length?<ul>{corrections.map((item)=><li key={item.id}><strong>{item.orderNo} · {eventTypeName(item.eventType)}</strong><span>{item.periodMonth.slice(0,7)} · {item.status} · 申请人 {item.requestedBy}</span><div className="row-actions">{isHr&&item.status==="pending"?<><button onClick={()=>post(`/api/accounting-corrections/${item.id}/approve`,{note:decisionNote})}>批准</button><button onClick={()=>post(`/api/accounting-corrections/${item.id}/reject`,{note:decisionNote})}>驳回</button></>:null}{isHr&&item.status==="approved"?<button onClick={()=>post(`/api/accounting-corrections/${item.id}/revoke`,{note:decisionNote})}>撤销</button>:null}{isLeader&&item.status==="approved"?<button onClick={()=>setExecution(item)}>执行更正</button>:null}</div></li>)}</ul>:<p>暂无更正申请。</p>}</div><div><h3>历史核对</h3>{reviews.length?<ul>{reviews.map((item)=><li key={item.id}><strong>{item.orderNo} · {item.conclusion}</strong><span>{item.status} · 核对人 {item.requestedBy} · 依据 {item.evidence}</span>{isHr&&item.status==="pending"?<div className="row-actions"><button onClick={()=>post(`/api/historical-order-reviews/${item.id}/approve`,{note:decisionNote})}>批准并解析</button><button onClick={()=>post(`/api/historical-order-reviews/${item.id}/reject`,{note:decisionNote})}>驳回</button></div>:null}</li>)}</ul>:<p>暂无历史核对记录。</p>}</div></div>
    {execution?<Modal title={`执行更正 · ${execution.orderNo}`} note={`获批范围：${execution.periodMonth.slice(0,7)} / ${eventTypeName(execution.eventType)}`} onClose={()=>setExecution(null)}><form noValidate className="business-form" onSubmit={executeCorrection}>{["revenue_change","first_include"].includes(execution.eventType)?<Field label={execution.eventType==="revenue_change"?"调整后营业额":"首次计入金额"} type="number" value={executionAmount} onChange={setExecutionAmount}/>:null}<Field label="执行原因" value={executionReason} onChange={setExecutionReason}/><div className="modal-actions"><button type="button" onClick={()=>setExecution(null)}>取消</button><button type="submit" disabled={busy}>确认追加更正事件</button></div></form></Modal>:null}
  </section>;
}

function OrderSelect({orders,value,onChange}:{orders:Order[];value:string;onChange:(value:string)=>void}){return <label className="field"><span>订单</span><select aria-label="订单" value={orders.some((order)=>order.id===value)?value:""} onChange={(event)=>onChange(event.target.value)}><option value="">请选择当前列表中的订单</option>{orders.map((order)=><option key={order.id} value={order.id}>{order.orderNo} · {order.customerName}</option>)}</select></label>;}

function CreateOrder({ onClose, onSaved }: { onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState(initialOrder);
  const [people, setPeople] = useState<Array<{ id:string; displayName:string }>>([]);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  useEffect(() => { fetch("/api/performance/people").then(async (response) => {
    const data = await response.json() as { people?:Array<{ id:string; displayName:string }>; message?:string };
    if (!response.ok) throw new Error(data.message ?? "业务员列表加载失败");
    setPeople(data.people ?? []);
  }).catch((reason) => setError(reason instanceof Error ? reason.message : "业务员列表加载失败")); }, []);
  function set(name: keyof typeof form, value: string) { setForm((current) => ({ ...current, [name]: value })); }
  async function submit(event: FormEvent) {
    event.preventDefault(); setSaving(true); setError("");
    try {
      const response = await apiFetch("/api/performance/orders", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...form, salespersonPersonId: Number(form.salespersonPersonId), amount: Number(form.amount) }) });
      const data = await response.json() as { message?: string };
      if (!response.ok) throw new Error(data.message ?? "订单入账失败");
      await onSaved();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "订单入账失败"); }
    finally { setSaving(false); }
  }
  return <Modal title="录入订单业绩" note="组织归属按业务员和收到日期自动解析并固化，后续只能追加更正事件" onClose={onClose}><form noValidate className="business-form" onSubmit={submit}><div className="form-grid"><Field label="订单编号" value={form.orderNo} onChange={(v) => set("orderNo",v)}/><Field label="收到日期" value={form.sourceReceivedOn} type="date" onChange={(v) => set("sourceReceivedOn",v)}/><Field label="客户名称" value={form.customerName} onChange={(v) => set("customerName",v)}/><Field label="客户单位" value={form.customerUnit} onChange={(v) => set("customerUnit",v)}/><label className="field"><span>业务区域</span><select required value={form.businessRegionCode} onChange={(event) => set("businessRegionCode",event.target.value)}><option value="">请选择</option>{standardBusinessRegions.map(([code,name]) => <option key={code} value={code}>{name}</option>)}</select></label><label className="field"><span>业务员</span><select required value={form.salespersonPersonId} onChange={(event) => set("salespersonPersonId",event.target.value)}><option value="">请选择</option>{people.map((person) => <option key={person.id} value={person.id}>{person.displayName}</option>)}</select></label><Field label="服务类型" value={form.serviceType} onChange={(v) => set("serviceType",v)}/><Field label="营业额" value={form.amount} type="number" onChange={(v) => set("amount",v)}/><Field label="入账原因" value={form.reason} onChange={(v) => set("reason",v)}/></div>{error ? <p className="form-error">{error}</p> : null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit" disabled={saving}>{saving ? "正在入账…" : "确认入账"}</button></div></form></Modal>;
}

function AdjustOrder({ order, canEdit, onClose, onSaved }: { order: Order; canEdit: boolean; onClose: () => void; onSaved: () => Promise<void> }) {
  const [events,setEvents]=useState<PerformanceEvent[]>([]);
  const [allowed,setAllowed]=useState<string[]>([]);
  const [lifecycle,setLifecycle]=useState<OrderLifecycle>(order.lifecycleState);
  const [loading,setLoading]=useState(true);
  const [type, setType] = useState("");
  const [amount, setAmount] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState("");
  const [saving,setSaving]=useState(false);
  const idempotencyKey=useRef(crypto.randomUUID());
  useEffect(()=>{
    const controller=new AbortController();
    fetch(`/api/performance/orders/${order.id}/events`,{signal:controller.signal}).then(async(response)=>{
      const data=await response.json() as {events?:PerformanceEvent[];lifecycleState?:OrderLifecycle;allowedActions?:string[];message?:string};
      if(!response.ok)throw new Error(data.message??"事件链加载失败");
      const nextAllowed=data.allowedActions??[];setEvents(data.events??[]);setLifecycle(data.lifecycleState??order.lifecycleState);setAllowed(nextAllowed);setType((current)=>nextAllowed.includes(current)?current:(nextAllowed[0]??""));
    }).catch((failure)=>{if(failure instanceof DOMException&&failure.name==="AbortError")return;setError(failure instanceof Error?failure.message:"事件链加载失败");}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});
    return()=>controller.abort();
  },[order.id,order.lifecycleState]);
  async function submit(event: FormEvent) {
    event.preventDefault();if(saving)return;setSaving(true);setError("");
    const payload = { type, reason, idempotencyKey:idempotencyKey.current, ...(type === "revenue_change" ? { newAmount: Number(amount) } : {}), ...(type === "first_include" ? { amount: Number(amount) } : {}) };
    try{
      const response = await apiFetch(`/api/performance/orders/${order.id}/events`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) });
      const data = await response.json() as { message?: string };
      if (!response.ok) { setError(data.message ?? "调整入账失败"); return; }
      await onSaved();
    }finally{setSaving(false);}
  }
  return <Modal title={order.orderNo} note={`${order.customerName} · 当前营业额 ${formatMoney(order.currentRevenue)} · 计入 ${formatMoney(order.countedAmount)}`} onClose={onClose}><section className="event-ledger" aria-labelledby="event-ledger-title"><div className="event-ledger-heading"><div><h3 id="event-ledger-title">不可变事件链</h3><p>{loading?"正在读取事件…":`${events.length} 条事件 · 按服务端账本序号排列`}</p></div><Status state={lifecycle}/></div>{!loading&&events.length?<ol>{events.map((item)=><li key={item.id}><span className="event-sequence" aria-label={`第 ${item.sequence} 条事件`}>{item.sequence}</span><div className="event-content"><div className="event-summary"><strong>{eventTypeName(item.eventType)}</strong><b className={Number(item.deltaAmount)<0?"negative":""}>{Number(item.deltaAmount)>0?"+":""}{formatMoney(item.deltaAmount)}</b>{item.resultingLifecycleState?<Status state={item.resultingLifecycleState}/>:<span className="legacy-semantic-note">原始状态未推断</span>}</div><dl><div><dt>业务日 / 记账月</dt><dd>{item.occurredOn} / {item.accountingMonth.slice(0,7)}</dd></div><div><dt>操作时间</dt><dd>{formatOperationTime(item.occurredAt)}</dd></div><div><dt>投影结果</dt><dd>营业额 {formatMoney(item.resultingCurrentRevenue)} · 计入 {formatMoney(item.resultingCountedAmount)}</dd></div><div><dt>原因 / 操作者</dt><dd>{item.reason||"—"} / {item.actorName||"历史导入"}</dd></div><div><dt>组织快照</dt><dd>{[item.departmentName,item.groupName].filter(Boolean).join(" / ")||"—"} · 组长 {item.leaderName||"—"} · 主管 {item.supervisorName||"—"}</dd></div></dl></div></li>)}</ol>:!loading&&!error?<p className="event-empty">没有可显示的事件。</p>:null}</section>{error ? <p className="form-error event-error" role="alert">{error}</p> : null}{!loading&&canEdit && allowed.length ? <form noValidate className="business-form event-form" onSubmit={submit}><div className="event-options">{allowed.includes("revenue_change") ? <button type="button" className={type==="revenue_change"?"selected":""} onClick={() => setType("revenue_change")}><RefreshCw size={17}/>修改营业额</button> : null}{allowed.includes("pause") ? <button type="button" className={type==="pause"?"selected":""} onClick={() => setType("pause")}><PauseCircle size={17}/>整单暂停</button> : null}{allowed.includes("restart") ? <button type="button" className={type==="restart"?"selected":""} onClick={() => setType("restart")}><PlayCircle size={17}/>订单重启</button> : null}{allowed.includes("first_include") ? <button type="button" className={type==="first_include"?"selected":""} onClick={() => setType("first_include")}><Plus size={17}/>首次计入</button> : null}</div><p className="form-note">操作时间和记账月由服务器确定，组织快照按该业务日的有效任职自动解析。</p><div className="form-grid">{type === "revenue_change" || type === "first_include" ? <Field label={type === "revenue_change" ? "调整后营业额" : "首次计入金额"} value={amount} type="number" onChange={setAmount}/> : null}<Field label="原因（必填）" value={reason} onChange={setReason}/></div><div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit" disabled={saving} aria-busy={saving}>{saving?"正在追加…":"确认追加事件"}</button></div></form> : !loading?<div className="permission-note">{lifecycle==="historical_review_required"?"该历史订单需要先完成核对与人事批准，当前不能追加事件。":"当前订单状态没有可执行操作，或当前角色仅可查看。"}</div>:null}</Modal>;
}

function Field({ label, value, onChange, type="text" }: { label: string; value: string; onChange: (value: string) => void; type?: string }) { return <label className="field"><span>{label}</span><input required value={value} type={type} min={type === "number" ? "0" : undefined} step={type === "number" ? "0.01" : undefined} onChange={(event) => onChange(event.target.value)}/></label>; }
function Modal({ title, note, onClose, children }: { title: string; note: string; onClose: () => void; children: ReactNode }) { const titleId=useId();const noteId=useId();const dialogRef=useRef<HTMLElement>(null);const closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const prior=document.activeElement instanceof HTMLElement?document.activeElement:null;const root=document.getElementById("root");const priorOverflow=document.body.style.overflow;root?.setAttribute("inert","");root?.setAttribute("aria-hidden","true");document.body.style.overflow="hidden";const dialog=dialogRef.current;dialog?.focus();function keydown(event:KeyboardEvent){if(event.key==="Escape"){event.preventDefault();closeRef.current();return;}if(event.key!=="Tab"||!dialog)return;const controls=[...dialog.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[href],[tabindex]:not([tabindex="-1"])')].filter((item)=>!item.hasAttribute("hidden"));if(!controls.length){event.preventDefault();dialog.focus();return;}const first=controls[0]!;const last=controls.at(-1)!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}document.addEventListener("keydown",keydown);return()=>{document.removeEventListener("keydown",keydown);root?.removeAttribute("inert");root?.removeAttribute("aria-hidden");document.body.style.overflow=priorOverflow;prior?.focus();};},[]);return createPortal(<div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section ref={dialogRef} tabIndex={-1} className="modal" role="dialog" aria-modal="true" aria-labelledby={titleId} aria-describedby={noteId}><header><div><h2 id={titleId}>{title}</h2><p id={noteId}>{note}</p></div><button onClick={onClose} aria-label="关闭">×</button></header>{children}</section></div>,document.body); }
function Status({ state }: { state: OrderLifecycle }) { const names:Record<OrderLifecycle,string> = { draft:"草稿", active:"正向计入", paused:"已暂停", zero:"零金额",historical_review_required:"待历史核对" }; return <span className={`status status-${state}`}>{names[state]}</span>; }
function formatMoney(value: string | number) { return new Intl.NumberFormat("zh-CN", { style: "currency", currency: "CNY", minimumFractionDigits: 2 }).format(Number(value)); }
function formatOperationTime(value:string){return new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).format(new Date(value));}
function eventTypeName(type: string) { return ({ initial:"首次录入", revenue_change:"营业额修改", pause:"整单暂停", restart:"订单重启", first_include:"首次计入", legacy_adjustment:"历史迁移",historical_review_resolution:"历史核对解析" } as Record<string,string>)[type] ?? type; }
function goalLevelName(level: string) { return ({ sales_manager:"销售经理总目标", department:"部门目标", group:"小组目标", personal:"个人目标" } as Record<string,string>)[level] ?? level; }
function goalStatusName(status: string) { return ({ draft:"草稿", pending_signature:"待责任人签名", pending_gm:"待总经理审批", pending_hr:"待人事审批", active:"已生效", rejected:"已拒绝", superseded:"已替代" } as Record<string,string>)[status] ?? status; }
function workflowStatusName(status:string){return ({pending:"待处理",accepted:"已接受，待重签",rejected:"已拒绝",withdrawn:"已撤回",invalidated:"已失效",completed:"已完成"} as Record<string,string>)[status]??status;}
function goalAuditName(action:string){return ({"goal.version_created":"创建目标版本","goal.version_signed":"责任人签名","goal.approved":"审批批准","goal.rejected":"审批拒绝","goal.version_superseded":"替代旧版本","goal.change_requested":"提交修改申请","goal.change_accepted":"接受修改申请","goal.change_rejected":"拒绝修改申请","goal.change_withdrawn":"撤回修改申请","goal.change_invalidated":"修改申请失效","goal.change_completed":"修改流程完成","goal.linkage_requested":"生成目标联动待办","goal.linkage_decided":"完成目标联动选择"} as Record<string,string>)[action]??action;}

function PanelTitle({ title, note }: { title: string; note: string }) { return <div className="panel-title"><div><h2>{title}</h2><p>{note}</p></div></div>; }
function Metric({label,value,note,warning,negative,onClick,actionLabel}:{label:string;value:string;note:string;warning?:boolean;negative?:boolean;onClick?:(()=>void)|undefined;actionLabel?:string|undefined}) { return <div className="metric"><span>{label}</span>{onClick?<button type="button" className={`metric-value-action${negative?" negative":""}`} aria-label={actionLabel} onClick={onClick}>{value}</button>:<strong className={negative?"negative":""}>{value}</strong>}<small className={warning?"warning":""}>{note}</small></div>; }
function TrendChart({year,monthly}:{year:string;monthly:Array<{month:string;total:string}>}) { const totals=new Map(monthly.map((item)=>[item.month,Number(item.total)]));const filled=Array.from({length:12},(_,index)=>totals.get(`${year}-${String(index+1).padStart(2,"0")}`)??0);const max=Math.max(1,...filled);const x=(index:number)=>44+index*(526/11);const points=filled.map((value,index)=>`${x(index)},${190-(value/max)*150}`).join(" ");return <div className="chart"><svg viewBox="0 0 590 220" role="img" aria-label={`${year}年1月至12月业绩折线图`}><g className="grid-lines">{[40,90,140,190].map((y)=><line key={y} x1="42" y1={y} x2="570" y2={y}/>)}</g><polyline points={points} fill="none" stroke="#2f6fed" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/>{filled.map((value,index)=><circle key={index} cx={x(index)} cy={190-(value/max)*150} r="5" fill="#fff" stroke="#2f6fed" strokeWidth="3"/>)}</svg><div className="chart-labels">{Array.from({length:12},(_,index)=><span key={index}>{index+1}月</span>)}</div></div>; }
